@app.route("/api/empleados", methods=["POST"])
@login_required(roles=["admin"])
def create_empleado():
    d = request.json
    if not d.get("legajo") or not d.get("nombre"):
        return jsonify({"error":"Legajo y nombre requeridos"}), 400
    if query("SELECT id FROM empleados WHERE legajo=?", (d["legajo"],), one=True):
        return jsonify({"error":"Legajo ya existe"}), 409
    lid = execute("INSERT INTO empleados (legajo,nombre,apellido,cargo,tipo,turno,obs,fecha_alta,fecha_baja) VALUES (?,?,?,?,?,?,?,?,?)",
        (d["legajo"],d["nombre"],d.get("apellido"),d.get("cargo"),d.get("tipo","Indirecto"),d.get("turno"),d.get("obs"),d.get("fecha_alta"),d.get("fecha_baja")))
    for cmid in (d.get("maquinas") or []):
        try: execute("INSERT OR IGNORE INTO empleado_maquinas (empleado_id,categoria_maquina_id) VALUES (?,?)", (lid, cmid))
        except: pass
    return jsonify({"ok":True,"id":lid}), 201

@app.route("/api/empleados/<int:eid>", methods=["PUT"])
@login_required(roles=["admin"])
def update_empleado(eid):
    d = request.json
    if d.get("legajo"):
        dup = query("SELECT id FROM empleados WHERE legajo=? AND id!=?", (d["legajo"], eid), one=True)
        if dup:
            return jsonify({"error":"Legajo ya existe"}), 409
    execute("UPDATE empleados SET legajo=?,nombre=?,apellido=?,cargo=?,tipo=?,turno=?,activo=?,obs=?,fecha_alta=?,fecha_baja=? WHERE id=?",
        (d.get("legajo"),d["nombre"],d["apellido"],d.get("cargo"),d.get("tipo","Indirecto"),d.get("turno"),
         1 if d.get("activo",True) else 0,d.get("obs"),d.get("fecha_alta"),d.get("fecha_baja"),eid))
    execute("DELETE FROM empleado_maquinas WHERE empleado_id=?", (eid,))
    for cmid in (d.get("maquinas") or []):
        try: execute("INSERT OR IGNORE INTO empleado_maquinas (empleado_id,categoria_maquina_id) VALUES (?,?)", (eid, cmid))
        except: pass
    return jsonify({"ok":True})

# ── Ordenes de cliente (comercial) ────────────────────────────────────────────
@app.route("/api/ordenes_cliente", methods=["GET"])
@login_required()
def get_ordenes_cliente():
    cid = request.args.get("cliente_id")
    est = request.args.get("estado")
    sql = "SELECT oc.*,c.razon cliente_nombre FROM ordenes_cliente oc JOIN clientes c ON c.id=oc.cliente_id"
    conds = []
    params = []
    if cid:
        conds.append("oc.cliente_id=?")
        params.append(cid)
    if est:
        conds.append("oc.estado=?")
        params.append(est)
    if conds:
        sql += " WHERE " + " AND ".join(conds)
    sql += " ORDER BY oc.id DESC"
    rows = query(sql, tuple(params)) if params else query(sql)
    result = []
    for r in rows:
        d = dict(r)
        try:
            d["items"] = [dict(x) for x in query("""SELECT i.*,p.nombre producto_nombre,p.codigo producto_codigo,
                o.numero ot_numero
                FROM ordenes_cliente_items i
                JOIN productos p ON p.id=i.producto_id
                LEFT JOIN ordenes o ON o.id=i.ot_id
                WHERE i.orden_cliente_id=?""", (r["id"],))]
        except Exception:
            # Fallback for old DBs missing ot_id column (migration will fix on restart)
            d["items"] = [dict(x) for x in query("""SELECT i.*,p.nombre producto_nombre,p.codigo producto_codigo,
                NULL as ot_id, NULL as ot_numero
                FROM ordenes_cliente_items i
                JOIN productos p ON p.id=i.producto_id
                WHERE i.orden_cliente_id=?""", (r["id"],))]
        for it in d["items"]:
            ots_item, cubierto = _ots_vinculadas_item(it["id"])
            it["ots"] = ots_item
            it["cantidad_cubierta"] = cubierto
        # Avance real de entrega: lo remitido sobre lo pedido (no "OT generada").
        total_req = sum(float(i["cantidad"]) for i in d["items"])
        total_ent = float(query("""SELECT COALESCE(SUM(ri.cantidad),0) total
            FROM remito_items ri
            JOIN remitos rem ON rem.id=ri.remito_id
            JOIN ordenes_cliente_items oci ON oci.id=ri.orden_cliente_item_id
            WHERE oci.orden_cliente_id=? AND rem.estado!='Anulado'""",
            (r["id"],), one=True)["total"])
        d["entregado"] = total_ent
        d["pct_entrega"] = min(100, round(total_ent/total_req*100)) if total_req else 0
        # Monto pedido (según lo cotizado) vs. monto a facturar (según lo
        # realmente remitido, ítem por ítem). Si se remitió por encima de lo
        # pedido en algún renglón, monto_entregado queda por encima de
        # monto_pedido — ese excedente es el que afecta el precio final.
        monto_pedido = 0.0
        monto_entregado = 0.0
        for i in d["items"]:
            precio_i = float(i.get("precio_unit") or 0)
            cant_pedida_i = float(i.get("cantidad") or 0)
            ent_i = float(query("""SELECT COALESCE(SUM(ri.cantidad),0) total
                FROM remito_items ri JOIN remitos rem ON rem.id=ri.remito_id
                WHERE ri.orden_cliente_item_id=? AND rem.estado!='Anulado'""",
                (i["id"],), one=True)["total"])
            i["cantidad_entregada"] = ent_i
            i["cantidad_restante"] = max(0, cant_pedida_i - ent_i)
            monto_pedido += cant_pedida_i * precio_i
            monto_entregado += ent_i * precio_i
        d["monto_pedido"] = monto_pedido
        d["monto_entregado"] = monto_entregado
        result.append(d)
    return jsonify(result)

@app.route("/api/ordenes_cliente", methods=["POST"])
@login_required(roles=["admin","vendedor"])
def create_orden_cliente():
    d = request.json
    if not d.get("cliente_id"):
        return jsonify({"error":"Cliente requerido"}), 400
    # Generar número automático solo a partir de los que ya tienen el
    # formato OC-CLI-####, ignorando números manuales con otro formato
    # (p.ej. "oc-2026", "OC-2026-0005") que rompían el cálculo por-1 y
    # podían generar un número ya usado (UNIQUE constraint failed).
    ultimos = query("SELECT numero FROM ordenes_cliente WHERE numero LIKE 'OC-CLI-%' ORDER BY id DESC")
    n = 1
    for r in ultimos:
        try:
            n = int(r["numero"].split("-")[-1]) + 1
            break
        except (ValueError, IndexError):
            continue
    numero = d.get("numero_oc") or f"OC-CLI-{n:04d}"
    # Check duplicate numero (también cubre el autogenerado: si por algún
    # motivo ya existe, se sigue incrementando hasta encontrar uno libre)
    if not d.get("numero_oc"):
        while query("SELECT id FROM ordenes_cliente WHERE numero=?", (numero,), one=True):
            n += 1
            numero = f"OC-CLI-{n:04d}"
    elif query("SELECT id FROM ordenes_cliente WHERE numero=?", (numero,), one=True):
        return jsonify({"error": f"El número {numero} ya existe"}), 409
    lid = execute("INSERT INTO ordenes_cliente (numero,cliente_id,fecha_entrega,estado,obs) VALUES (?,?,?,?,?)",
        (numero, d["cliente_id"], d.get("fecha_entrega"), d.get("estado","Recibida"), d.get("obs")))
    for item in d["items"]:
        if item.get("producto_id") and item.get("cantidad"):
            execute("""INSERT INTO ordenes_cliente_items
                (orden_cliente_id,producto_id,cantidad,precio_unit,fecha_deseada,obs)
                VALUES (?,?,?,?,?,?)""",
                (lid, item["producto_id"], item["cantidad"],
                 item.get("precio_unit",0), item.get("fecha_deseada"), item.get("obs")))
    return jsonify({"ok":True,"id":lid,"numero":numero}), 201




def _recalcular_tiempo_total_producto(prod_id):
    """Recalcula tiempo_total_hs de un producto sumando el tiempo de cada paso
    (orden). Si un paso tiene rutas alternativas (mismo número de orden, p.ej.
    2 procesos posibles para el mismo paso), se toma la más rápida como
    estimación — la ruta realmente usada se elige en Control de producción."""
    tot = query("""SELECT COALESCE(SUM(t),0) total FROM (
        SELECT MIN(tiempo_setup_min+tiempo_ciclo_min) t
        FROM proceso_operaciones WHERE producto_id=? GROUP BY orden)""",
        (prod_id,), one=True)["total"]
    execute("UPDATE productos SET tiempo_total_hs=? WHERE id=?", (round(tot/60,2), prod_id))

def calcular_tiempo_ciclo_total(prod_id, qty=1.0, _visitados=None):
    """Suma tiempo_ciclo_min de todas las operaciones (sin setup), recursivo.
    Si un material es un PT con proceso, suma también su tiempo de fabricación."""
    if _visitados is None:
        _visitados = set()
    if prod_id in _visitados:
        return 0.0
    _visitados.add(prod_id)

    # Tiempo de ciclo propio (si un paso tiene rutas alternativas con el
    # mismo número de orden, se toma la más rápida como estimación)
    ops = query("""SELECT COALESCE(SUM(t),0) s FROM (
        SELECT MIN(tiempo_ciclo_min) t FROM proceso_operaciones
        WHERE producto_id=? GROUP BY orden)""",
        (prod_id,), one=True)
    total = float(ops["s"] or 0) * qty

    # Tiempo de sub-productos (materiales que son PT)
    mats = query("""SELECT om.material_id, SUM(om.cantidad)*? AS total_cant,
        m.categoria, m.codigo
        FROM proceso_operaciones po
        JOIN operacion_materiales om ON om.operacion_id=po.id
        JOIN materiales m ON m.id=om.material_id
        WHERE po.producto_id=?
        GROUP BY om.material_id""", (qty, prod_id))

    for m in mats:
        if m["categoria"] == "Producto terminado":
            sub = query("SELECT id FROM productos WHERE codigo=? AND activo=1",
                        (m["codigo"],), one=True)
            if sub:
                total += calcular_tiempo_ciclo_total(
                    sub["id"], float(m["total_cant"] or 0), _visitados)
    return total

def calcular_costo_producto(prod_id, qty=1.0, _visitados=None):
    """Calcula costo_mat de un producto recursivamente.
    Si un material es un Producto terminado con proceso definido,
    su costo = costo de fabricarlo (materiales de sus operaciones)."""
    if _visitados is None:
        _visitados = set()
    if prod_id in _visitados:   # evitar ciclos
        return 0.0
    _visitados.add(prod_id)

    mats = query("""SELECT om.material_id, SUM(om.cantidad)*? AS total_cant,
        m.precio_unit, m.categoria, m.codigo
        FROM proceso_operaciones po
        JOIN operacion_materiales om ON om.operacion_id=po.id
        JOIN materiales m ON m.id=om.material_id
        WHERE po.producto_id=?
        GROUP BY om.material_id""", (qty, prod_id))

    costo_total = 0.0
    for m in mats:
        cant = float(m["total_cant"] or 0)
        if m["categoria"] == "Producto terminado":
            # Buscar si este PT tiene un producto-proceso definido
            sub_prod = query(
                "SELECT id FROM productos WHERE codigo=? AND activo=1",
                (m["codigo"],), one=True)
            if sub_prod:
                costo_total += calcular_costo_producto(sub_prod["id"], cant, _visitados)
                continue
        costo_total += float(m["precio_unit"] or 0) * cant
    return costo_total


def explotar_multinivel(prod_id, qty, cliente_id, fecha_entrega_padre, oc_numero,
                        nivel=0, _ots=None, _visitados=None):
    """Genera OT para prod_id y, recursivamente, OTs hijas para cada sub-producto
    que sea Producto terminado con proceso propio.
    Retorna (ot_id_padre, lista_de_ots_creadas)."""
    from datetime import datetime, timedelta
    import math
    if _ots is None: _ots = []
    if _visitados is None: _visitados = set()
    if prod_id in _visitados:
        return None, _ots
    _visitados.add(prod_id)

    prod = query("SELECT * FROM productos WHERE id=?", (prod_id,), one=True)
    if not prod:
        return None, _ots

    # Costo y tiempo
    costo_mat = calcular_costo_producto(prod_id, qty)
    ops_proc = query("SELECT * FROM proceso_operaciones WHERE producto_id=? ORDER BY CAST(orden AS INTEGER), orden",
                     (prod_id,))
    tiempo_std_min = sum(
        (op["tiempo_setup_min"] or 0) + (op["tiempo_ciclo_min"] or 0) * qty
        for op in ops_proc
    )
    dias_necesarios = max(1, math.ceil(tiempo_std_min / 480))
    if nivel == 0:
        fecha_ot = fecha_entrega_padre
    else:
        # Sub-OT necesita terminar antes que la padre
        try:
            fecha_padre_dt = datetime.strptime(fecha_entrega_padre, "%Y-%m-%d")
            fecha_ot = (fecha_padre_dt - timedelta(days=dias_necesarios + 1)).strftime("%Y-%m-%d")
        except Exception:
            fecha_ot = fecha_entrega_padre

    # Número OT
    last_ot = query("SELECT numero FROM ordenes ORDER BY id DESC LIMIT 1", one=True)
    try: n = int(last_ot["numero"].split("-")[1]) + 1 if last_ot else 1
    except: n = 1
    numero_ot = f"OT-{n:03d}"

    prefijo = "  " * nivel
    obs = f"{prefijo}Generada desde OC {oc_numero}" + (f" | Sub-producto niv.{nivel}" if nivel > 0 else "")

    ot_id = execute("""INSERT INTO ordenes
        (numero,cliente_id,producto_id,descripcion,cantidad,prioridad,estado,
         fecha_entrega,costo_mat,costo_mo,precio_venta,obs)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
        (numero_ot, cliente_id, prod_id,
         f"{prod['codigo']} — {prod['nombre']}",
         qty, "Normal", "Pendiente",
         fecha_ot, round(costo_mat, 2), round(tiempo_std_min, 0),
         float(prod["precio_venta"] or 0), obs))

    # Operaciones
    for op in ops_proc:
        execute("""INSERT INTO orden_operaciones
            (orden_id,proceso_op_id,orden,nombre,categoria_maquina_id,maquina_id,
             tiempo_setup_min,tiempo_ciclo_min,estado,qty_requerida,
             es_tercerizada,proveedor_id,precio_tercerizado,tiempo_minimo_dias)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (ot_id, op["id"], op["orden"], op["nombre"],
             op["categoria_maquina_id"], op["maquina_id"],
             op["tiempo_setup_min"], op["tiempo_ciclo_min"],
             "Pendiente", qty,
             op["es_tercerizada"] if "es_tercerizada" in op.keys() else 0,
             op["proveedor_id"] if "proveedor_id" in op.keys() else None,
             op["precio_tercerizado"] if "precio_tercerizado" in op.keys() else 0,
             op["tiempo_minimo_dias"] if "tiempo_minimo_dias" in op.keys() else 0))

    # Materiales — separar simples de sub-productos
    mats = query("""SELECT om.material_id, SUM(om.cantidad)*? AS total_cant,
        m.unidad, m.precio_unit, m.categoria, m.codigo
        FROM proceso_operaciones po
        JOIN operacion_materiales om ON om.operacion_id=po.id
        JOIN materiales m ON m.id=om.material_id
        WHERE po.producto_id=?
        GROUP BY om.material_id""", (qty, prod_id))

    for mat in mats:
        cant = float(mat["total_cant"] or 0)
        # Registrar el material en la OT (siempre, independientemente de si es sub-prod)
        execute("""INSERT INTO orden_materiales
            (orden_id,material_id,cantidad_requerida,cantidad_asignada,unidad)
            VALUES (?,?,?,0,?)""",
            (ot_id, mat["material_id"], cant, mat["unidad"]))

        # Si es PT con proceso propio → generar OT hija recursivamente
        if mat["categoria"] == "Producto terminado":
            sub_prod = query(
                """SELECT p.id FROM productos p
                   JOIN proceso_operaciones po ON po.producto_id=p.id
                   WHERE p.codigo=? AND p.activo=1
                   LIMIT 1""",
                (mat["codigo"],), one=True)
            if sub_prod:
                sub_ot_id, _ots = explotar_multinivel(
                    sub_prod["id"], cant, cliente_id, fecha_ot,
                    oc_numero, nivel + 1, _ots, _visitados)
            else:
                # PT sin proceso propio definido: no se puede fabricar (no
                # hay ruta que ejecutar) y tampoco se puede comprar en
                # Compras (regla del sistema: "Producto terminado" nunca es
                # comprable). Esto es un problema de configuración del
                # producto (le falta el proceso) — no se genera SC ni OT acá;
                # queda como faltante visible en la OT para resolverlo a mano
                # (definir el proceso del producto, o asignar/vincular un
                # lote existente desde "Lotes asignados").
                pass
        else:
            # Material real (no sub-producto de categoría "Producto
            # terminado"): puede tratarse igual de un producto fabricado en
            # planta que fue cargado como Insumo/Herramienta/Material en el
            # proceso (ej. un producto con proceso propio agregado como
            # insumo de otro). Si existe un producto activo con proceso
            # propio para este código Y el stock actual no alcanza para
            # cubrir lo que esta OT va a consumir, se genera una OT hija por
            # el FALTANTE (no por la cantidad total: lo que ya hay en stock
            # cubre esa parte y no hace falta fabricarlo de nuevo).
            sub_prod = query(
                """SELECT p.id FROM productos p
                   JOIN proceso_operaciones po ON po.producto_id=p.id
                   WHERE p.codigo=? AND p.activo=1
                   LIMIT 1""",
                (mat["codigo"],), one=True)
            if sub_prod:
                mat_stock = query("SELECT stock FROM materiales WHERE id=?",
                    (mat["material_id"],), one=True)
                stock_disp = float(mat_stock["stock"] or 0) if mat_stock else 0
                faltante = round(cant - stock_disp, 3)
                if faltante > 0:
                    sub_ot_id, _ots = explotar_multinivel(
                        sub_prod["id"], faltante, cliente_id, fecha_ot,
                        oc_numero, nivel + 1, _ots, _visitados)
                # Si el stock actual ya cubre lo requerido, no se genera OT.
            else:
                # Material real (no sub-producto): si su stock queda por debajo
                # del mínimo una vez descontado lo que esta OT va a consumir,
                # se dispara (o actualiza) automáticamente la SC correspondiente.
                # Esto es lo que cierra el flujo OC → SC → OT aux → OT final:
                # la OC dispara la explosión, que crea las OT (aux para el
                # sub-producto, final para la pieza pedida) y, en el mismo paso,
                # la SC para el material que falte comprar.
                auto_generar_sc_bajo_stock(
                    mat["material_id"],
                    f"explosión OC {oc_numero} → OT {numero_ot}")

    _generar_ott_para_ot(ot_id, numero_ot)

    _ots.append({
        "item": prod["nombre"],
        "cantidad": qty,
        "ot_numero": numero_ot,
        "ot_id": ot_id,
        "fecha_entrega": fecha_ot,
        "nivel": nivel,
        "costo_mat": round(costo_mat, 2),
    })
    return ot_id, _ots

@app.route("/api/ordenes_cliente/<int:ocid>/explotar", methods=["POST"])
@login_required(roles=["admin","vendedor","operario"])
def explotar_orden_cliente(ocid):
    """Genera OTs para cada ítem de la OC con explosión multinivel:
    si un material es un Producto terminado con proceso propio, genera OTs hijas."""
    from datetime import datetime, timedelta
    import math

    oc = query("SELECT * FROM ordenes_cliente WHERE id=?", (ocid,), one=True)
    if not oc: return jsonify({"error":"OC no encontrada"}), 404
    if oc["estado"] == "En proceso":
        return jsonify({"error":"Esta OC ya fue explotada"}), 409

    items = query("""SELECT i.*,p.nombre prod_nombre,p.codigo prod_codigo,
        p.tiempo_total_hs,p.costo_mat,p.precio_venta
        FROM ordenes_cliente_items i
        JOIN productos p ON p.id=i.producto_id
        WHERE i.orden_cliente_id=?""", (ocid,))

    if not items: return jsonify({"error":"La OC no tiene ítems"}), 400

    hoy = datetime.now()
    ots_todas = []

    for item in items:
        if item["ot_id"]:
            continue

        # Fecha entrega del nivel 0
        tiempo_hs = float(item["tiempo_total_hs"] or 1)
        dias_necesarios = math.ceil(tiempo_hs * float(item["cantidad"]) / 8)
        fecha_entrega = item["fecha_deseada"] or             (hoy + timedelta(days=max(dias_necesarios, 1))).strftime("%Y-%m-%d")

        # Explosión multinivel recursiva
        ot_id, ots_item = explotar_multinivel(
            item["producto_id"], float(item["cantidad"]),
            oc["cliente_id"], fecha_entrega, oc["numero"])

        if ot_id:
            execute("UPDATE ordenes_cliente_items SET ot_id=? WHERE id=?",
                    (ot_id, item["id"]))
            execute("INSERT OR IGNORE INTO orden_cliente_item_ots (item_id,ot_id) VALUES (?,?)",
                    (item["id"], ot_id))

        ots_todas.extend(ots_item)

    execute("UPDATE ordenes_cliente SET estado='En proceso' WHERE id=?", (ocid,))
    return jsonify({"ok": True, "ots": ots_todas})

def _ots_vinculadas_item(item_id):
    """Todas las OTs vinculadas a un ítem de OC de cliente (puede haber más
    de una, repartiendo la cantidad pedida entre varias OTs del mismo
    material/producto), más la suma de sus cantidades."""
    rows = query("""SELECT o.id ot_id, o.numero ot_numero, o.cantidad ot_cantidad, o.estado ot_estado
        FROM orden_cliente_item_ots ocio JOIN ordenes o ON o.id=ocio.ot_id
        WHERE ocio.item_id=? ORDER BY ocio.id""", (item_id,))
    ots = [dict(r) for r in rows]
    cubierto = sum(float(r["ot_cantidad"] or 0) for r in ots)
    return ots, cubierto

def _pct_entrega_oc(ocid):
    """Avance real de entrega de una OC (lo remitido sobre lo pedido),
    misma lógica que en el listado de OCs. Se usa para bloquear
    vincular/desvincular OTs una vez que la OC llegó al 100%."""
    total_req = float(query("SELECT COALESCE(SUM(cantidad),0) s FROM ordenes_cliente_items WHERE orden_cliente_id=?",
        (ocid,), one=True)["s"])
    total_ent = float(query("""SELECT COALESCE(SUM(ri.cantidad),0) total
        FROM remito_items ri
        JOIN remitos rem ON rem.id=ri.remito_id
        JOIN ordenes_cliente_items oci ON oci.id=ri.orden_cliente_item_id
        WHERE oci.orden_cliente_id=? AND rem.estado!='Anulado'""",
        (ocid,), one=True)["total"])
    return min(100, round(total_ent/total_req*100)) if total_req else 0

@app.route("/api/ordenes/vinculables", methods=["GET"])
@login_required(roles=["admin","vendedor","operario"])
def get_ordenes_vinculables():
    """OTs existentes (cualquier estado salvo canceladas) que todavía no
    están vinculadas a ningún ítem de OC de cliente, filtrables por pieza
    (producto). Se pueden vincular varias a un mismo ítem: el límite lo pone
    la suma de sus cantidades contra lo pedido por el ítem, no la cantidad
    individual de cada OT."""
    producto_id = request.args.get("producto_id")
    pieza = request.args.get("pieza")
    sql = """SELECT o.*, pr.codigo prod_codigo, pr.nombre prod_nombre
        FROM ordenes o
        LEFT JOIN productos pr ON pr.id=o.producto_id
        WHERE o.id NOT IN (SELECT ot_id FROM orden_cliente_item_ots)
        AND o.estado NOT IN ('Cancelada')"""
    params = []
    if producto_id:
        sql += " AND o.producto_id=?"
        params.append(producto_id)
    elif pieza:
        sql += " AND (pr.codigo LIKE ? OR pr.nombre LIKE ? OR o.descripcion LIKE ?)"
        params += [f"%{pieza}%", f"%{pieza}%", f"%{pieza}%"]
    sql += " ORDER BY o.id DESC"
    rows = query(sql, tuple(params))
    return jsonify([dict(r) for r in rows])

@app.route("/api/ordenes_cliente_items/<int:item_id>/ots_vinculadas", methods=["GET"])
@login_required()
def get_ots_vinculadas_item(item_id):
    ots, cubierto = _ots_vinculadas_item(item_id)
    return jsonify({"ots": ots, "cubierto": cubierto})

@app.route("/api/ordenes_cliente_items/<int:item_id>/vincular_ot", methods=["POST"])
@login_required(roles=["admin","vendedor","operario"])
def vincular_ot_item(item_id):
    """Vincula manualmente una OT ya existente (no generada por explosión) a
    un ítem de OC de cliente. Se pueden vincular varias OTs del mismo
    material/producto a un mismo ítem, repartiendo la cantidad pedida entre
    ellas, pero la opción se bloquea apenas la suma de lo vinculado iguala o
    supera la cantidad que pide el ítem de la OC."""
    d = request.json or {}
    ot_id = d.get("ot_id")
    if not ot_id: return jsonify({"error":"OT requerida"}), 400
    item = query("SELECT * FROM ordenes_cliente_items WHERE id=?", (item_id,), one=True)
    if not item: return jsonify({"error":"Ítem de OC no encontrado"}), 404
    if _pct_entrega_oc(item["orden_cliente_id"]) >= 100:
        return jsonify({"error":"La OC ya está 100% entregada: no se pueden vincular más OTs"}), 409
    ot = query("SELECT * FROM ordenes WHERE id=?", (ot_id,), one=True)
    if not ot: return jsonify({"error":"OT no encontrada"}), 404
    if ot["producto_id"] and item["producto_id"] and ot["producto_id"] != item["producto_id"]:
        return jsonify({"error":"La OT es de otro material/producto distinto al del ítem"}), 400
    ya_vinculada = query("SELECT id FROM orden_cliente_item_ots WHERE ot_id=?", (ot_id,), one=True)
    if ya_vinculada: return jsonify({"error":"Esa OT ya está vinculada a otro ítem"}), 409
    _ots, cubierto = _ots_vinculadas_item(item_id)
    if cubierto >= float(item["cantidad"]):
        return jsonify({"error":"Ya se cubrió la cantidad pedida por este ítem: no se pueden vincular más OTs"}), 409
    execute("INSERT INTO orden_cliente_item_ots (item_id,ot_id) VALUES (?,?)", (item_id, ot_id))
    if not item["ot_id"]:
        execute("UPDATE ordenes_cliente_items SET ot_id=? WHERE id=?", (ot_id, item_id))
    execute("UPDATE ordenes_cliente SET estado='En proceso' WHERE id=?", (item["orden_cliente_id"],))
    return jsonify({"ok": True})

@app.route("/api/ordenes_cliente_items/<int:item_id>/desvincular_ot/<int:ot_id>", methods=["DELETE"])
@login_required(roles=["admin","vendedor","operario"])
def desvincular_ot_item(item_id, ot_id):
    """Quita el vínculo entre una OT y un ítem de OC de cliente."""
    item = query("SELECT * FROM ordenes_cliente_items WHERE id=?", (item_id,), one=True)
    if not item: return jsonify({"error":"Ítem de OC no encontrado"}), 404
    if _pct_entrega_oc(item["orden_cliente_id"]) >= 100:
        return jsonify({"error":"La OC ya está 100% entregada: no se pueden desvincular OTs"}), 409
    execute("DELETE FROM orden_cliente_item_ots WHERE item_id=? AND ot_id=?", (item_id, ot_id))
    if item["ot_id"] == ot_id:
        otra = query("SELECT ot_id FROM orden_cliente_item_ots WHERE item_id=? ORDER BY id LIMIT 1", (item_id,), one=True)
        execute("UPDATE ordenes_cliente_items SET ot_id=? WHERE id=?", (otra["ot_id"] if otra else None, item_id))
    return jsonify({"ok": True})

@app.route("/api/ordenes_cliente/<int:ocid>", methods=["PUT"])
@login_required(roles=["admin","vendedor"])
def update_orden_cliente(ocid):
    d = request.json
    execute("UPDATE ordenes_cliente SET estado=?,fecha_entrega=?,obs=? WHERE id=?",
        (d.get("estado"), d.get("fecha_entrega"), d.get("obs"), ocid))
    # Update items if provided (only items without OTs assigned)
    if "items" in d:
        execute("DELETE FROM ordenes_cliente_items WHERE orden_cliente_id=? AND (ot_id IS NULL OR ot_id=0)", (ocid,))
        for item in (d["items"] or []):
            if item.get("producto_id") and item.get("cantidad"):
                execute("""INSERT INTO ordenes_cliente_items
                    (orden_cliente_id,producto_id,cantidad,precio_unit,fecha_deseada,obs)
                    VALUES (?,?,?,?,?,?)""",
                    (ocid, item["producto_id"], item["cantidad"],
                     item.get("precio_unit",0), item.get("fecha_deseada"), item.get("obs")))
    return jsonify({"ok":True})

# ── MRP ampliado: consolidar OC-cliente → generar OTs ────────────────────────
def _generar_sc_materiales_faltantes(oid, numero_ot, motivo=""):
    """Revisa los materiales que requiere una OT (por ejemplo una OT auxiliar
    recién creada) y, para cada uno que esté bajo stock mínimo o cuyo stock
    actual no alcance para cubrir lo que esta OT necesita, genera (o
    actualiza) una Solicitud de Compra. La cantidad pedida siempre apunta a
    reponer hasta el "Máximo" configurado en el material (stock_max), no solo
    lo justo para esta OT — igual que el resto del sistema de reposición.
    Si el material no tiene Máximo configurado, se usa como objetivo lo que
    esta OT necesita.
    Devuelve la lista de SC creadas/actualizadas."""
    creadas = []
    mats = query("""SELECT om.material_id, om.cantidad_requerida, m.codigo, m.descripcion,
        m.unidad, m.categoria, m.stock, m.stock_min, m.stock_max,
        COALESCE((SELECT SUM(MAX(0, l.cantidad_activa - COALESCE(l.cantidad_reservada,0)))
                   FROM lotes l
                   WHERE l.material_id=om.material_id
                     AND l.cantidad_activa > COALESCE(l.cantidad_reservada,0)), 0) AS disponible_libre,
        (SELECT COUNT(*) FROM lotes l2 WHERE l2.material_id=om.material_id) AS n_lotes
        FROM orden_materiales om JOIN materiales m ON m.id=om.material_id
        WHERE om.orden_id=?""", (oid,))
    for mat in mats:
        if mat["categoria"] not in ("Material", "Insumo", "Herramienta"):
            # "Producto terminado" nunca genera Solicitud de Compra: no se
            # compra en Compras. Si hace falta más de lo que hay en stock, se
            # resuelve fabricándolo (OT auxiliar) — eso lo cubre
            # _gap_analysis_materiales, que vuelve a correr sobre esta OT
            # recién creada (ver _gap_analysis_materiales_multipass).
            continue
        requerido = float(mat["cantidad_requerida"] or 0)
        # Igual que en el gap analysis del MRP: si el material tiene
        # trazabilidad por lote, el stock relevante para decidir la SC es
        # el "Disponible libre" (cantidad_activa - cantidad_reservada de
        # los lotes), no el stock total, porque parte de ese stock puede
        # estar ya reservado a nivel de lote para otras OTs.
        if mat["n_lotes"]:
            stock = float(mat["disponible_libre"] or 0)
        else:
            stock = float(mat["stock"] or 0)
        stock_min = float(mat["stock_min"] or 0)
        stock_max = float(mat["stock_max"] or 0)
        # Objetivo de reposición: el Máximo del material. Si no hay Máximo
        # configurado, al menos lo que esta OT necesita.
        objetivo = stock_max if stock_max > 0 else max(stock_min, requerido)
        # Dispara SC si el material está bajo su mínimo, o si — aunque esté
        # por encima del mínimo — el stock disponible no alcanza para cubrir
        # lo que esta OT puntualmente necesita.
        bajo_minimo = stock_min > 0 and stock < stock_min
        insuficiente_para_ot = stock < requerido
        if not bajo_minimo and not insuficiente_para_ot:
            continue
        faltante = round(max(objetivo, requerido) - stock, 3)
        if faltante <= 0:
            continue

        sc_exist = query("""SELECT id,cantidad FROM solicitudes_compra
            WHERE material_id=? AND estado IN ('Pendiente','Cotizada','En evaluación')
            ORDER BY id DESC LIMIT 1""", (mat["material_id"],), one=True)
        if sc_exist:
            if float(sc_exist["cantidad"] or 0) < faltante:
                execute("""UPDATE solicitudes_compra SET cantidad=?, obs=? WHERE id=?""",
                    (faltante,
                     f"Actualizada automáticamente: material requerido por OT {numero_ot}, faltante {faltante} {mat['unidad']} (objetivo: Máximo {objetivo}).",
                     sc_exist["id"]))
                creadas.append({"numero": None, "material": mat["descripcion"], "cantidad": faltante, "actualizada": True})
            continue

        sc_num = next_numero_sc()
        tipo_sc = "Productiva" if mat["categoria"] == "Material" else "Indirecta"
        execute("""INSERT INTO solicitudes_compra
            (numero,tipo,descripcion,material_id,cantidad,unidad,urgencia,estado,obs)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (sc_num, tipo_sc,
             f"Material requerido por {numero_ot} — {mat['descripcion']}",
             mat["material_id"], faltante, mat["unidad"],
             "Alta", "Pendiente",
             f"Generada automáticamente: material requerido por OT {numero_ot}, faltante {faltante} {mat['unidad']} (objetivo: Máximo {objetivo}). {motivo}"))
        creadas.append({"numero": sc_num, "material": mat["descripcion"], "cantidad": faltante})
    return creadas

@app.route("/api/mrp/consolidar", methods=["POST"])
@login_required(roles=["admin","operario"])
def mrp_consolidar():
    d = request.json
    oc_ids = d.get("oc_ids", [])
    if not oc_ids: return jsonify({"error":"Seleccioná al menos una OC de cliente"}), 400
    placeholders = ",".join("?" * len(oc_ids))
    items = query(f"""SELECT i.producto_id,SUM(i.cantidad) AS total_qty,
        p.nombre producto_nombre,p.codigo,p.costo_mat,p.costo_mo,p.precio_venta,
        MAX(oc.cliente_id) cliente_id,
        COALESCE(i.fecha_deseada, MAX(oc.fecha_entrega)) fecha_entrega,
        GROUP_CONCAT(i.id) AS item_ids
        FROM ordenes_cliente_items i
        JOIN ordenes_cliente oc ON oc.id=i.orden_cliente_id
        JOIN productos p ON p.id=i.producto_id
        WHERE oc.id IN ({placeholders}) AND (i.ot_id IS NULL OR i.ot_id=0)
        GROUP BY i.producto_id, i.fecha_deseada""", oc_ids)
    ots_creadas = []
    for item in items:
        last = query("SELECT numero FROM ordenes ORDER BY id DESC LIMIT 1", one=True)
        try: n = int(last["numero"].split("-")[1])+1 if last else 1
        except: n = 1
        numero = f"OT-{n:03d}"

        # Calcular tiempo estándar (min) en base a las operaciones del proceso,
        # igual que en explotar_multinivel, en vez de copiar costo_mo del producto.
        ops_proc_item = query(
            "SELECT * FROM proceso_operaciones WHERE producto_id=? ORDER BY CAST(orden AS INTEGER), orden",
            (item["producto_id"],))
        tiempo_std_min = sum(
            (op["tiempo_setup_min"] or 0) + (op["tiempo_ciclo_min"] or 0) * item["total_qty"]
            for op in ops_proc_item
        )

        # Costo de materiales: se calcula dinámicamente en base a la receta
        # actual del producto (igual que en explotar_multinivel / calcular_costo_producto),
        # en vez de usar productos.costo_mat, que es un valor estático que puede
        # estar desactualizado o en 0 si nunca se recalculó a mano.
        costo_mat_item = calcular_costo_producto(item["producto_id"], item["total_qty"])

        oid = execute("""INSERT INTO ordenes
            (numero,cliente_id,producto_id,descripcion,cantidad,prioridad,estado,fecha_entrega,costo_mat,costo_mo,precio_venta)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
            (numero,item["cliente_id"],item["producto_id"],
             f"Fabricación {item['producto_nombre']} — generado por MRP",
             item["total_qty"],"Normal","Pendiente",item["fecha_entrega"],
             round(costo_mat_item, 2),round(tiempo_std_min, 0),item["precio_venta"]))
        populate_ops_internal(oid, item["producto_id"], item["total_qty"])
        populate_mats_internal(oid, item["producto_id"], item["total_qty"])
        # Vincular esta OT a los renglones de OC que la originaron
        # (para que "Remitir a cliente" pueda cruzar PT → OC)
        if item["item_ids"]:
            item_id_list = [int(x) for x in str(item["item_ids"]).split(",") if x]
            if item_id_list:
                ph_items = ",".join("?" * len(item_id_list))
                execute(f"UPDATE ordenes_cliente_items SET ot_id=? WHERE id IN ({ph_items})",
                        [oid] + item_id_list)
                for iid in item_id_list:
                    execute("INSERT OR IGNORE INTO orden_cliente_item_ots (item_id,ot_id) VALUES (?,?)",
                            (iid, oid))
        # ── Generate OTTs for tercerized operations (idempotente) ─────────
        # Nota: la OTT ya no dispara una Solicitud de Compra (SC-TERC) por el
        # servicio tercerizado. El flujo de la OTT es exclusivamente
        # remitir → recibir (ver /api/ott/<id>/emitir_remito y
        # /api/ott/<id>/registrar_retorno); no genera compras.
        _generar_ott_para_ot(oid, numero)
        ots_creadas.append({"numero":numero,"producto":item["producto_nombre"],"cantidad":item["total_qty"]})
    execute(f"UPDATE ordenes_cliente SET estado='En proceso' WHERE id IN ({placeholders})", oc_ids)

    solicitudes_creadas, ots_auxiliares = _gap_analysis_materiales_multipass()
    return jsonify({"ok":True,"ots":ots_creadas,"ots_auxiliares":ots_auxiliares,"solicitudes_compra":solicitudes_creadas})


def _gap_analysis_materiales_multipass(max_passes=5):
    """Corre _gap_analysis_materiales() repetidas veces: si una pasada genera
    una OT auxiliar nueva (fabricación de un Producto Terminado faltante),
    esa OT auxiliar trae sus propios materiales, que a su vez pueden incluir
    OTRO Producto Terminado faltante (BOM multinivel) — eso recién queda
    visible para el análisis en la pasada siguiente, porque la pasada actual
    ya leyó orden_materiales antes de insertar la nueva OT. Se repite hasta
    que una pasada no genere nada nuevo, con un tope de pasadas para no
    entrar en loop infinito si hay una referencia circular entre productos.
    Devuelve (solicitudes_creadas, ots_auxiliares) acumuladas de todas las pasadas."""
    solicitudes_tot, ots_tot = [], []
    for _ in range(max_passes):
        solicitudes, ots_aux = _gap_analysis_materiales()
        solicitudes_tot.extend(solicitudes)
        ots_tot.extend(ots_aux)
        # Si esta pasada no creó ninguna OT auxiliar NUEVA (las "actualizada"
        # son sobre una OT que ya existía de una pasada anterior a este
        # llamado), no hay nada más que una pasada nueva pueda destapar.
        if not any(not o.get("actualizada") for o in ots_aux):
            break
    return solicitudes_tot, ots_tot


def _gap_analysis_materiales():
    """Analiza el stock disponible contra todas las OTs activas (Pendiente/En
    proceso) y genera automáticamente Solicitudes de Compra u OTs auxiliares
    (para Producto Terminado fabricado en planta) para cubrir los faltantes.
    Es agnóstico del origen de las OTs (OC de cliente, pronóstico de venta,
    etc.) — corre sobre el estado actual de orden_materiales. Devuelve
    (solicitudes_creadas, ots_auxiliares)."""
    # ── Material gap analysis: check stock vs all pending OTs ─────────────────
    solicitudes_creadas = []
    ots_auxiliares = []
    # Get all active OTs (including just-created) that have unassigned materials
    gap_mats = query("""
        SELECT om.material_id, m.codigo, m.descripcion, m.unidad, m.categoria,
               m.producto_id AS pt_producto_id, m.stock_max,
               SUM(om.cantidad_requerida) AS total_req,
               SUM(COALESCE(om.cantidad_asignada,0)) AS total_asign,
               m.stock AS stock_actual,
               COALESCE((SELECT SUM(MAX(0, l.cantidad_activa - COALESCE(l.cantidad_reservada,0)))
                          FROM lotes l
                          WHERE l.material_id=om.material_id
                            AND l.cantidad_activa > COALESCE(l.cantidad_reservada,0)), 0) AS disponible_libre
        FROM orden_materiales om
        JOIN ordenes o ON o.id=om.orden_id
        JOIN materiales m ON m.id=om.material_id
        WHERE o.estado IN ('Pendiente','En proceso')
        GROUP BY om.material_id""")
    for mat in gap_mats:
        total_req   = float(mat["total_req"] or 0)
        total_asign = float(mat["total_asign"] or 0)
        # Para materiales con trazabilidad por lote (los que tienen lotes
        # cargados), el faltante se calcula contra el "Disponible libre"
        # real (lotes.cantidad_activa - cantidad_reservada), no contra el
        # stock total del material, porque parte de ese stock puede ya
        # estar reservado para otras OTs a nivel de lote. Si el material no
        # maneja lotes (insumos/herramientas sin trazabilidad), se usa el
        # stock general como antes.
        tiene_lotes = query("SELECT 1 FROM lotes WHERE material_id=? LIMIT 1",
                             (mat["material_id"],), one=True)
        if tiene_lotes:
            stock = float(mat["disponible_libre"] or 0)
        else:
            stock = float(mat["stock_actual"] or 0)
        # Cantidad neta que falta asignar a las OTs activas (lo ya asignado
        # no vuelve a contarse). El faltante real es lo que excede al stock
        # actualmente disponible: si el stock alcanza para cubrir todo lo
        # requerido, no hay faltante; si no alcanza, la SC debe pedir
        # exactamente la diferencia (cubre al máximo con el stock existente,
        # sin sobre-pedir).
        reservado   = max(0, total_req - total_asign)
        faltante    = max(0, reservado - stock)
        if faltante <= 0:
            continue

        # Si el insumo faltante es un Producto Terminado fabricado en planta
        # (tiene proceso propio definido), el faltante NO se resuelve con
        # una SC de compra: se resuelve fabricándolo. Se genera una OT
        # "auxiliar" de ese producto, por la cantidad necesaria para llenar
        # el inventario hasta su "Máximo" (materiales.stock_max) — no solo
        # lo justo para esta OT, para no quedar disparando una OT aux nueva
        # cada vez que se corre el MRP.
        prod_pt = None
        if mat["categoria"] == "Producto terminado" and mat["pt_producto_id"]:
            prod_pt = query("""SELECT p.id,p.nombre,p.codigo FROM productos p
                JOIN proceso_operaciones po ON po.producto_id=p.id
                WHERE p.id=? AND p.activo=1 LIMIT 1""", (mat["pt_producto_id"],), one=True)

        if prod_pt:
            stock_max = float(mat["stock_max"] or 0)
            cantidad_ot = round(max(faltante, stock_max - stock), 3)
            if cantidad_ot <= 0:
                continue

            # No duplicar: si ya hay una OT auxiliar Pendiente/En proceso
            # para este producto (generada por esta misma lógica), se
            # actualiza su cantidad en vez de crear otra.
            ot_exist = query("""SELECT id,numero,cantidad FROM ordenes
                WHERE producto_id=? AND estado IN ('Pendiente','En proceso')
                  AND obs LIKE 'OT auxiliar generada automáticamente por MRP%'
                ORDER BY id DESC LIMIT 1""", (prod_pt["id"],), one=True)
            if ot_exist:
                if float(ot_exist["cantidad"] or 0) < cantidad_ot:
                    execute("UPDATE ordenes SET cantidad=? WHERE id=?", (cantidad_ot, ot_exist["id"]))
                    # La cantidad de la OT aux cambió: recalculamos sus
                    # materiales requeridos (proporcional a la nueva cantidad)
                    # y volvemos a chequear si algún material quedó faltante.
                    execute("DELETE FROM orden_materiales WHERE orden_id=?", (ot_exist["id"],))
                    populate_mats_internal(ot_exist["id"], prod_pt["id"], cantidad_ot)
                    scs_mat = _generar_sc_materiales_faltantes(
                        ot_exist["id"], ot_exist["numero"],
                        motivo=f"Insumo de OT auxiliar {ot_exist['numero']} ({prod_pt['nombre']}).")
                    solicitudes_creadas.extend(scs_mat)
                    ots_auxiliares.append({"numero": ot_exist["numero"], "producto": prod_pt["nombre"],
                                            "cantidad": cantidad_ot, "actualizada": True})
                continue

            last = query("SELECT numero FROM ordenes ORDER BY id DESC LIMIT 1", one=True)
            try: n = int(last["numero"].split("-")[1])+1 if last else 1
            except: n = 1
            numero_aux = f"OT-{n:03d}"

            ops_proc_aux = query(
                "SELECT * FROM proceso_operaciones WHERE producto_id=? ORDER BY CAST(orden AS INTEGER), orden",
                (prod_pt["id"],))
            tiempo_std_aux = sum(
                (op["tiempo_setup_min"] or 0) + (op["tiempo_ciclo_min"] or 0) * cantidad_ot
                for op in ops_proc_aux)
            costo_mat_aux = calcular_costo_producto(prod_pt["id"], cantidad_ot)

            oid_aux = execute("""INSERT INTO ordenes
                (numero,cliente_id,producto_id,descripcion,cantidad,prioridad,estado,fecha_entrega,costo_mat,costo_mo,precio_venta,obs)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
                (numero_aux, None, prod_pt["id"],
                 f"{prod_pt['codigo']} — {prod_pt['nombre']} (OT auxiliar por faltante de insumo)",
                 cantidad_ot, "Alta", "Pendiente", date.today().isoformat(),
                 round(costo_mat_aux, 2), round(tiempo_std_aux, 0), 0,
                 f"OT auxiliar generada automáticamente por MRP. Faltante detectado: {round(faltante,3)} {mat['unidad']}. Se pide hasta el máximo ({stock_max})."))
            populate_ops_internal(oid_aux, prod_pt["id"], cantidad_ot)
            populate_mats_internal(oid_aux, prod_pt["id"], cantidad_ot)
            ots_auxiliares.append({"numero": numero_aux, "producto": prod_pt["nombre"], "cantidad": cantidad_ot})

            # La OT auxiliar recién creada tiene sus propios materiales
            # (los que hacen falta para fabricar el insumo). Si alguno está
            # bajo stock o no alcanza para cubrir esta OT, se genera la SC
            # correspondiente, pidiendo hasta el Máximo de ese material.
            scs_mat = _generar_sc_materiales_faltantes(
                oid_aux, numero_aux,
                motivo=f"Insumo de OT auxiliar {numero_aux} ({prod_pt['nombre']}).")
            solicitudes_creadas.extend(scs_mat)
            continue

        # Caso normal: material real, o Producto Terminado sin proceso propio
        # (se compra hecho) → falta resolverlo por compra (SC).
        # Si ya hay una SC abierta para este material, no duplicamos: si su
        # cantidad ya cubre el faltante actual la dejamos; si quedó corta
        # (p.ej. porque el faltante creció con esta corrida de MRP), la
        # actualizamos para que cubra el faltante real en vez de dejarla
        # desactualizada.
        sc_exist = query("""SELECT id,cantidad FROM solicitudes_compra
            WHERE material_id=? AND estado IN ('Pendiente','En evaluación')
            ORDER BY id DESC LIMIT 1""", (mat["material_id"],), one=True)
        if sc_exist:
            if float(sc_exist["cantidad"] or 0) < faltante:
                execute("""UPDATE solicitudes_compra SET cantidad=?,
                    obs=? WHERE id=?""",
                    (round(faltante, 3),
                     f"Actualizada automáticamente por MRP. Faltante: {round(faltante,3)} {mat['unidad']}",
                     sc_exist["id"]))
                solicitudes_creadas.append({"numero":None,"material":mat["descripcion"],"cantidad":round(faltante,3),"actualizada":True})
        else:
            last_sc = query("SELECT numero FROM solicitudes_compra WHERE numero LIKE 'SC-PROD-%' ORDER BY id DESC LIMIT 1", one=True)
            try: sc_n = int(last_sc["numero"].split("-")[2])+1 if last_sc else 1
            except: sc_n = 1
            sc_num = f"SC-PROD-{sc_n:04d}"
            execute("""INSERT INTO solicitudes_compra
                (numero,tipo,descripcion,material_id,cantidad,unidad,urgencia,estado,obs)
                VALUES (?,?,?,?,?,?,?,?,?)""",
                (sc_num, "Productiva",
                 f"Material requerido por MRP — {mat['descripcion']}",
                 mat["material_id"], round(faltante, 3), mat["unidad"],
                 "Alta", "Pendiente",
                 f"Generada automáticamente por MRP. Faltante: {round(faltante,3)} {mat['unidad']}"))
            solicitudes_creadas.append({"numero":sc_num,"material":mat["descripcion"],"cantidad":round(faltante,3)})
    return solicitudes_creadas, ots_auxiliares


@app.route("/api/mrp/pronostico_meses", methods=["POST"])
@login_required(roles=["admin","operario"])
def mrp_pronostico_meses():
    """Devuelve los meses con renglones pendientes de convertir para los
    pronósticos de venta seleccionados, para que el usuario elija con cuál
    mes consolidar."""
    d = request.json or {}
    pron_ids = d.get("pronostico_ids") or ([d["pronostico_id"]] if d.get("pronostico_id") else [])
    if not pron_ids: return jsonify({"error":"Seleccioná al menos un pronóstico"}), 400
    placeholders = ",".join("?" * len(pron_ids))
    meses = query(f"""SELECT i.mes, COUNT(*) AS items_pendientes, SUM(i.cantidad) AS total_qty
        FROM pronostico_venta_items i
        WHERE i.pronostico_id IN ({placeholders}) AND i.cantidad>0
          AND i.id NOT IN (SELECT item_id FROM pronostico_item_ots)
        GROUP BY i.mes ORDER BY i.mes""", pron_ids)
    return jsonify([dict(r) for r in meses])

@app.route("/api/mrp/consolidar_pronostico", methods=["POST"])
@login_required(roles=["admin","operario"])
def mrp_consolidar_pronostico():
    """Genera OTs de fabricación (para stock, sin OC de cliente vinculada) a
    partir de los renglones de un pronóstico de venta. Se debe indicar el mes
    a consolidar ("mes", formato YYYY-MM): se consolidan ese mes y todos los
    meses anteriores que todavía tengan renglones pendientes (ej: si se
    consolida septiembre, también se consolidan agosto, julio, etc. si
    estaban pendientes), ya que se asume que si se llegó a un mes es porque
    los anteriores también deben quedar cubiertos. Se genera una OT distinta
    por cada mes consolidado (nunca se mezclan cantidades de distintos meses
    en una misma OT), y se evita duplicar OTs si el renglón ya fue convertido
    previamente (se registra en pronostico_item_ots)."""
    d = request.json
    pron_ids = d.get("pronostico_ids") or ([d["pronostico_id"]] if d.get("pronostico_id") else [])
    if not pron_ids: return jsonify({"error":"Seleccioná al menos un pronóstico"}), 400
    mes = (d.get("mes") or "").strip()
    if not mes: return jsonify({"error":"Seleccioná el mes a consolidar"}), 400
    placeholders = ",".join("?" * len(pron_ids))
    pronosticos = query(f"SELECT * FROM pronosticos_venta WHERE id IN ({placeholders})", pron_ids)
    if not pronosticos: return jsonify({"error":"Pronóstico no encontrado"}), 404

    # Se agrupa por producto, cliente y mes (mes <= mes elegido) de forma que
    # cada mes pendiente hasta el elegido (inclusive) genere sus propias OTs
    # (nunca se mezclan cantidades de meses distintos en una misma OT).
    items = query(f"""SELECT i.producto_id, pv.cliente_id, i.mes, SUM(i.cantidad) AS total_qty,
        p.nombre producto_nombre, p.codigo, p.precio_venta,
        GROUP_CONCAT(i.id) AS item_ids, GROUP_CONCAT(DISTINCT pv.codigo) AS pron_codigos
        FROM pronostico_venta_items i
        JOIN pronosticos_venta pv ON pv.id=i.pronostico_id
        JOIN productos p ON p.id=i.producto_id
        WHERE i.pronostico_id IN ({placeholders}) AND i.cantidad>0 AND i.mes<=?
          AND i.id NOT IN (SELECT item_id FROM pronostico_item_ots)
        GROUP BY i.producto_id, pv.cliente_id, i.mes
        ORDER BY i.mes""", pron_ids + [mes])
    if not items:
        return jsonify({"error":"No hay renglones pendientes de convertir hasta el mes seleccionado"}), 400

    ots_creadas = []
    for item in items:
        last = query("SELECT numero FROM ordenes ORDER BY id DESC LIMIT 1", one=True)
        try: n = int(last["numero"].split("-")[1])+1 if last else 1
        except: n = 1
        numero = f"OT-{n:03d}"

        ops_proc_item = query(
            "SELECT * FROM proceso_operaciones WHERE producto_id=? ORDER BY CAST(orden AS INTEGER), orden",
            (item["producto_id"],))
        tiempo_std_min = sum(
            (op["tiempo_setup_min"] or 0) + (op["tiempo_ciclo_min"] or 0) * item["total_qty"]
            for op in ops_proc_item
        )
        costo_mat_item = calcular_costo_producto(item["producto_id"], item["total_qty"])

        oid = execute("""INSERT INTO ordenes
            (numero,cliente_id,producto_id,descripcion,cantidad,prioridad,estado,fecha_entrega,costo_mat,costo_mo,precio_venta,obs)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
            (numero, item["cliente_id"], item["producto_id"],
             f"Fabricación {item['producto_nombre']} — generado por pronóstico {item['pron_codigos']} ({item['mes']})",
             item["total_qty"], "Normal", "Pendiente", None,
             round(costo_mat_item, 2), round(tiempo_std_min, 0), item["precio_venta"],
             f"Generada automáticamente a partir del/los pronóstico(s) de venta {item['pron_codigos']} — mes {item['mes']}."))
        populate_ops_internal(oid, item["producto_id"], item["total_qty"])
        populate_mats_internal(oid, item["producto_id"], item["total_qty"])

        # Vincular los renglones del pronóstico que originaron esta OT, para
        # no volver a convertirlos si se corre el consolidado de nuevo.
        item_id_list = [int(x) for x in str(item["item_ids"]).split(",") if x]
        for iid in item_id_list:
            execute("INSERT OR IGNORE INTO pronostico_item_ots (item_id,ot_id) VALUES (?,?)", (iid, oid))

        ots_creadas.append({"numero": numero, "producto": item["producto_nombre"], "cantidad": item["total_qty"], "mes": item["mes"]})

    solicitudes_creadas, ots_auxiliares = _gap_analysis_materiales_multipass()
    return jsonify({"ok":True,"ots":ots_creadas,"ots_auxiliares":ots_auxiliares,"solicitudes_compra":solicitudes_creadas})


def populate_ops_internal(oid, prod_id, qty):
    ops = query("SELECT * FROM proceso_operaciones WHERE producto_id=? ORDER BY CAST(orden AS INTEGER), orden", (prod_id,))
    for op in ops:
        execute("""INSERT INTO orden_operaciones
            (orden_id,proceso_op_id,orden,nombre,categoria_maquina_id,maquina_id,
             tiempo_setup_min,tiempo_ciclo_min,estado,qty_requerida,
             es_tercerizada,proveedor_id,precio_tercerizado,tiempo_minimo_dias)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (oid,op["id"],op["orden"],op["nombre"],op["categoria_maquina_id"],op["maquina_id"],
             op["tiempo_setup_min"],op["tiempo_ciclo_min"],"Pendiente",qty,
             op["es_tercerizada"] if "es_tercerizada" in op.keys() else 0,
             op["proveedor_id"] if "proveedor_id" in op.keys() else None,
             op["precio_tercerizado"] if "precio_tercerizado" in op.keys() else 0,
             op["tiempo_minimo_dias"] if "tiempo_minimo_dias" in op.keys() else 0))

def populate_mats_internal(oid, prod_id, qty):
    mats = query("""SELECT om.material_id,SUM(om.cantidad)*? AS total,m.unidad
        FROM proceso_operaciones po JOIN operacion_materiales om ON om.operacion_id=po.id
        JOIN materiales m ON m.id=om.material_id
        WHERE po.producto_id=? GROUP BY om.material_id""", (qty, prod_id))
    for mat in mats:
        execute("INSERT INTO orden_materiales (orden_id,material_id,cantidad_requerida,cantidad_asignada,unidad) VALUES (?,?,?,0,?)",
            (oid, mat["material_id"], mat["total"], mat["unidad"]))

# ── Novedades de producción ───────────────────────────────────────────────────
@app.route("/api/novedades/corregir_rendimiento", methods=["GET"])
@login_required(roles=["admin"])
def preview_corregir_novedades():
    """Previsualiza qué novedades cambiarían su rendimiento/desvío al
    recalcularlos usando el tiempo de ciclo que tiene la operación en SU
    propia OT (orden_operaciones.tiempo_ciclo_min) como estándar, ya que
    ese es el valor vigente para esa orden puntual (puede haber sido
    ajustado y diferir del proceso/plantilla). Solo si la OT no tiene un
    valor propio cargado (0/NULL) se recurre al de la plantilla
    (proceso_operaciones.tiempo_ciclo_min) como respaldo. No modifica nada."""
    rows = query("""
        SELECT n.id, n.numero, n.cantidad_producida, n.tiempo_real_min, n.tiempo_perdido,
               n.rendimiento_pct, n.desvio,
               COALESCE(NULLIF(oo.tiempo_ciclo_min, 0), po.tiempo_ciclo_min, 1) AS std_ciclo
        FROM novedades_produccion n
        JOIN orden_operaciones oo ON oo.id = n.orden_operacion_id
        LEFT JOIN proceso_operaciones po ON po.id = oo.proceso_op_id
        WHERE n.tiempo_real_min > 0
        ORDER BY n.id
    """)

    afectadas = []
    for r in rows:
        std_ciclo = r["std_ciclo"] or 1
        t_real = r["tiempo_real_min"]
        qty = r["cantidad_producida"]
        t_productivo = max(t_real, 0.1)
        rendimiento_nuevo = round((qty / t_productivo) / (1 / std_ciclo) * 100, 1)
        rendimiento_nuevo = min(rendimiento_nuevo, 999)
        desvio_nuevo = 1 if rendimiento_nuevo < 80 else 0

        if abs((r["rendimiento_pct"] or 0) - rendimiento_nuevo) < 0.05 and r["desvio"] == desvio_nuevo:
            continue

        afectadas.append({
            "id": r["id"], "numero": r["numero"],
            "tiempo_real_min": t_real, "tiempo_perdido": r["tiempo_perdido"],
            "rendimiento_actual": r["rendimiento_pct"], "desvio_actual": r["desvio"],
            "rendimiento_nuevo": rendimiento_nuevo, "desvio_nuevo": desvio_nuevo
        })

    return jsonify({"afectadas": afectadas, "total": len(afectadas)})

@app.route("/api/novedades/corregir_rendimiento", methods=["POST"])
@login_required(roles=["admin"])
def aplicar_corregir_novedades():
    """Aplica la corrección de rendimiento/desvío calculada por
    preview_corregir_novedades sobre todas las novedades afectadas."""
    rows = query("""
        SELECT n.id, n.cantidad_producida, n.tiempo_real_min,
               n.rendimiento_pct, n.desvio,
               COALESCE(NULLIF(oo.tiempo_ciclo_min, 0), po.tiempo_ciclo_min, 1) AS std_ciclo
        FROM novedades_produccion n
        JOIN orden_operaciones oo ON oo.id = n.orden_operacion_id
        LEFT JOIN proceso_operaciones po ON po.id = oo.proceso_op_id
        WHERE n.tiempo_real_min > 0
        ORDER BY n.id
    """)

    updates = []
    for r in rows:
        std_ciclo = r["std_ciclo"] or 1
        t_real = r["tiempo_real_min"]
        qty = r["cantidad_producida"]
        t_productivo = max(t_real, 0.1)
        rendimiento_nuevo = round((qty / t_productivo) / (1 / std_ciclo) * 100, 1)
        rendimiento_nuevo = min(rendimiento_nuevo, 999)
        desvio_nuevo = 1 if rendimiento_nuevo < 80 else 0

        if abs((r["rendimiento_pct"] or 0) - rendimiento_nuevo) < 0.05 and r["desvio"] == desvio_nuevo:
            continue
        updates.append((rendimiento_nuevo, desvio_nuevo, r["id"]))

    for rendimiento_nuevo, desvio_nuevo, nid in updates:
        execute("UPDATE novedades_produccion SET rendimiento_pct=?, desvio=? WHERE id=?",
            (rendimiento_nuevo, desvio_nuevo, nid))

    return jsonify({"ok": True, "corregidas": len(updates)})

@app.route("/api/novedades", methods=["GET"])
@login_required()
def get_novedades():
    oid = request.args.get("orden_id")
    operacion_id = request.args.get("operacion_id")
    empleado_id = request.args.get("empleado_id")
    producto_id = request.args.get("producto_id")
    cliente_id = request.args.get("cliente_id")
    maquina_id = request.args.get("maquina_id")
    fecha_desde = request.args.get("fecha_desde")
    fecha_hasta = request.args.get("fecha_hasta")
    ocultar_completadas = request.args.get("ocultar_completadas")
    sql = """SELECT n.*,e.nombre||' '||e.apellido empleado_nombre,
        m.codigo||' — '||m.nombre maquina_nombre,
        oo.nombre operacion_nombre, oo.orden op_orden,
        o.numero ot_numero, o.producto_id, o.cliente_id, o.estado ot_estado,
        p.nombre producto_nombre, p.codigo producto_codigo,
        c.razon cliente_nombre
        FROM novedades_produccion n
        LEFT JOIN empleados e ON e.id=n.empleado_id
        LEFT JOIN maquinas m ON m.id=n.maquina_id
        JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id
        JOIN ordenes o ON o.id=n.orden_id
        LEFT JOIN productos p ON p.id=o.producto_id
        LEFT JOIN clientes c ON c.id=o.cliente_id"""
    where = []
    params = []
    if oid: where.append("n.orden_id=?"); params.append(oid)
    if operacion_id: where.append("n.orden_operacion_id=?"); params.append(operacion_id)
    if empleado_id: where.append("n.empleado_id=?"); params.append(empleado_id)
    if producto_id: where.append("o.producto_id=?"); params.append(producto_id)
    if cliente_id: where.append("o.cliente_id=?"); params.append(cliente_id)
    if maquina_id: where.append("n.maquina_id=?"); params.append(maquina_id)
    if fecha_desde: where.append("n.fecha>=?"); params.append(fecha_desde)
    if fecha_hasta: where.append("n.fecha<=?"); params.append(fecha_hasta)
    if ocultar_completadas in ("1","true"): where.append("o.estado NOT IN ('Completada','Cancelada')")
    sql += (" WHERE "+" AND ".join(where)) if where else ""
    sql += " ORDER BY n.id DESC"
    if not where: sql += " LIMIT 200"
    rows = query(sql, tuple(params)) if params else query(sql)
    return jsonify([dict(r) for r in rows])

def _bloqueo_terc_previo(orden_id, orden_num):
    """Si hay una operación tercerizada ANTERIOR (orden menor) en la misma OT
    que todavía no está Completada, la OT queda pausada: no se puede avanzar
    con operaciones posteriores hasta que el proveedor devuelva el lote y
    quede Aprobado (ver ott_registrar_retorno / update_lote).
    Devuelve la fila bloqueante o None si no hay bloqueo."""
    try:
        orden_num_int = int(orden_num)
    except Exception:
        return None
    return query("""SELECT nombre, orden FROM orden_operaciones
        WHERE orden_id=? AND es_tercerizada=1 AND estado!='Completada'
          AND CAST(orden AS INTEGER) < ?
        ORDER BY CAST(orden AS INTEGER) LIMIT 1""",
        (orden_id, orden_num_int), one=True)

def _tope_terc_previa(orden_id, orden_num):
    """Devuelve la operación tercerizada ANTERIOR (orden menor) más cercana
    en la misma OT junto con lo que ya aprobó/produjo hasta el momento
    (qty_producida) — o None si no hay ninguna. Esto se usa para permitir
    cargar novedades en la operación siguiente de forma incremental,
    topeadas a lo que la tercerizada ya entregó/aprobó hasta ahora (ver
    _sync_ott_retorno_a_operacion: si de 100 llegaron y se aprobaron 50, acá
    se puede cargar hasta 50, no hay que esperar a que vuelva/apruebe todo).

    IMPORTANTE: a diferencia de _bloqueo_terc_previo (que deja de bloquear
    en cuanto la tercerizada llega a 'Completada'), este tope NO filtra por
    estado. Tiene que seguir aplicando incluso después de que la tercerizada
    quede Completada, porque sigue siendo el límite físico real de lo que
    volvió aprobado del proveedor: si ya se cargaron 50 acá (mientras la
    tercerizada estaba en 50/100) y después se aprueban en OTRO lote las 50
    rechazadas restantes (tercerizada ahora en 100/100, Completada), lo
    disponible para seguir cargando esta operación es 100 (total aprobado)
    MENOS lo ya cargado (50) = 50, no 100 de nuevo. Si acá se dejara de
    aplicar el tope al completarse la tercerizada, se perdía esa resta y se
    podía volver a cargar hasta el total (100) ignorando lo ya declarado —
    ese era el bug: quedaba limitado únicamente por el estado de la
    operación tercerizada en vez de por la cantidad real ya aprobada."""
    try:
        orden_num_int = int(orden_num)
    except Exception:
        return None
    return query("""SELECT id, nombre, orden, qty_producida FROM orden_operaciones
        WHERE orden_id=? AND es_tercerizada=1
          AND CAST(orden AS INTEGER) < ?
        ORDER BY CAST(orden AS INTEGER) DESC LIMIT 1""",
        (orden_id, orden_num_int), one=True)

@app.route("/api/novedades", methods=["POST"])
@login_required(roles=["admin","operario"])
def create_novedad():
    d = request.json
    if not d.get("orden_id") or not d.get("orden_operacion_id"):
        return jsonify({"error":"orden_id y orden_operacion_id requeridos"}), 400
    qty = float(d.get("cantidad_producida",0) or 0)
    piezas_no_ok = float(d.get("piezas_observadas",0) or 0)
    t_real = float(d.get("tiempo_real_min",0))
    if qty<=0 and piezas_no_ok<=0: return jsonify({"error":"Cargue cantidad OK o piezas NO OK"}), 400
    if t_real<=0: return jsonify({"error":"El tiempo debe ser mayor a 0"}), 400
    # La vinculación de lote a un material de la OT se hace exclusivamente
    # desde Órdenes de trabajo → "Lotes asignados" (botón "Asignar lote").
    # Acá, al declarar una novedad, solo se CONSUME el lote que ya haya sido
    # vinculado por ese camino — no se acepta elegir/crear un vínculo nuevo
    # desde este endpoint.

    op = query("""SELECT oo.*,po.tiempo_ciclo_min std_ciclo,po.producto_id
        FROM orden_operaciones oo
        LEFT JOIN proceso_operaciones po ON po.id=oo.proceso_op_id
        WHERE oo.id=?""", (d["orden_operacion_id"],), one=True)
    if not op: return jsonify({"error":"Operación no encontrada"}), 404

    # ── Operación tercerizada: no se carga por Novedades. Se completa sola
    # cuando vuelve el lote del proveedor (OTT → Lotes → Aprobado). ────────
    if op["es_tercerizada"]:
        return jsonify({"error": "Esta operación es tercerizada: no se carga por Novedades. "
            "Se completa automáticamente cuando vuelve el lote del proveedor (OTT) y queda Aprobado en Lotes."}), 400

    # ── OT pausada por una operación tercerizada ANTERIOR sin completar:
    # NO se bloquea todo — se topea lo que se puede cargar en esta operación
    # a lo que la tercerizada ya entregó/aprobó hasta el momento (uso
    # incremental). Ej: de 100 llegaron y se aprobaron 50 → se puede cargar
    # esta operación hasta 50 en total, sin esperar a que vuelva/apruebe el
    # resto. ─────────────────────────────────────────────────────────────
    qty_req_op = float(op["qty_requerida"] or 0)
    qty_prod_op = float(op["qty_producida"] or 0)
    tope_terc = _tope_terc_previa(d["orden_id"], op["orden"])
    if tope_terc:
        disponible_terc = float(tope_terc["qty_producida"] or 0)
        if disponible_terc <= 0.0001:
            return jsonify({"error": f"OT pausada: la operación tercerizada \"{tope_terc['nombre']}\" "
                f"(orden {tope_terc['orden']}) todavía no tiene nada recibido/aprobado. No se pueden "
                f"cargar novedades de esta operación hasta que vuelva y se apruebe al menos una parte "
                f"del lote del proveedor."}), 400
        if qty_prod_op + qty > disponible_terc + 0.0001:
            return jsonify({"error": f"Cantidad excede lo disponible de la operación tercerizada "
                f"\"{tope_terc['nombre']}\" (orden {tope_terc['orden']}): aprobado hasta ahora "
                f"{disponible_terc:g}, ya cargado en esta operación {qty_prod_op:g}, "
                f"disponible para esta novedad {max(0, disponible_terc - qty_prod_op):g}."}), 400

    # ── Si la operación está marcada como "Completada", no se pueden cargar
    # más novedades. Si el usuario la volvió a poner "En proceso" manualmente
    # (por ejemplo desde Control de Producción) después de haber llegado al
    # 100%, se le permite seguir cargando novedades: el bloqueo es por
    # ESTADO, no por haber alcanzado la cantidad requerida. Solo se vuelve a
    # bloquear cuando el usuario la marca Completada de nuevo (manual o
    # automáticamente al llegar al 100%). ───────────────────────────────────
    if op["estado"] == "Completada":
        return jsonify({"error": "No se puede cargar más novedades: la operación ya está marcada como Completada (%s/%s piezas). Volvé a ponerla en proceso para seguir cargando." % (qty_prod_op, qty_req_op)}), 400

    std_ciclo = op["tiempo_ciclo_min"] or op["std_ciclo"] or 1
    t_perdido = float(d.get("tiempo_perdido") or 0)
    # tiempo_real = tiempo EFECTIVAMENTE trabajado (ya neto).
    # tiempo_perdido = tiempo aparte que no se trabajó (no está incluido en tiempo_real).
    # Por lo tanto el rendimiento se calcula sobre tiempo_real solo, sin restar nada.
    t_productivo = max(t_real, 0.1)
    rendimiento = round((qty / t_productivo) / (1 / std_ciclo) * 100, 1)
    rendimiento = min(rendimiento, 999)
    desvio = 1 if rendimiento < 80 else 0

    # ── VALIDACIONES DE STOCK/LOTES: se hacen TODAS antes de insertar nada,
    # así si algo falla no queda la novedad guardada a medias (ver bug donde
    # el INSERT ocurría antes de estas validaciones y la novedad quedaba
    # creada aunque el sistema mostrara un error de stock insuficiente). ──
    mats_op = []
    insumos_op = []
    lotes_info = {}
    if op["proceso_op_id"]:
        mats_op_all = query("""SELECT om.*, m.descripcion descripcion, m.categoria categoria
            FROM operacion_materiales om JOIN materiales m ON m.id=om.material_id
            WHERE om.operacion_id=?""", (op["proceso_op_id"],))
        mats_op = [m for m in mats_op_all if m["categoria"] not in ("Insumo", "Herramienta")]
        insumos_op = [m for m in mats_op_all if m["categoria"] in ("Insumo", "Herramienta")]
    # ── Material semielaborado de una OTT anterior (no está en el BOM del
    # producto porque se generó dinámicamente al recibir el retorno del
    # proveedor) — ver _materiales_ott_pendientes_por_operacion. Se chequea
    # siempre, incluso si esta operación no tiene proceso_op_id (agregada a
    # mano), porque este material no depende de la plantilla de proceso.
    for extra in _materiales_ott_pendientes_por_operacion(d["orden_id"], d["orden_operacion_id"]):
        if not any(m["material_id"] == extra["material_id"] for m in mats_op):
            mats_op.append(extra)

    # Validar stock disponible para insumos (se descuentan recién al
    # completar la OT, pero acá se valida que alcance considerando lo
    # ya comprometido por otras operaciones/novedades de la misma OT
    # más lo que agrega esta novedad, para no permitir cargar una
    # novedad que termine consumiendo más de lo que hay en stock).
    if insumos_op:
        errores_ins = []
        for ins in insumos_op:
            consumo_incremental = ins["cantidad"] * qty
            comprometido = query("""SELECT COALESCE(SUM(om.cantidad * oo.qty_producida),0) c
                FROM orden_operaciones oo
                JOIN operacion_materiales om ON om.operacion_id=oo.proceso_op_id
                WHERE oo.orden_id=? AND om.material_id=?""",
                (d["orden_id"], ins["material_id"]), one=True)["c"] or 0
            mat_stock = query("SELECT stock FROM materiales WHERE id=?", (ins["material_id"],), one=True)
            stock_disp = float(mat_stock["stock"] or 0) if mat_stock else 0
            total_necesario = float(comprometido) + consumo_incremental
            if total_necesario > stock_disp:
                faltante = round(total_necesario - stock_disp, 3)
                errores_ins.append(f"Stock insuficiente de insumo \"{ins['descripcion']}\" (stock {stock_disp}, requerido {round(total_necesario,3)}, faltan {faltante})")
        if errores_ins:
            return jsonify({"error": "No se puede confirmar la novedad: " + " | ".join(errores_ins)}), 400

    if mats_op:
        errores = []
        for mat in mats_op:
            consumo = mat["cantidad"] * qty
            # Si el material fue añadido al proceso DESPUÉS de creada la
            # OT, no está en la foto de orden_materiales (tomada al
            # crear la OT) y por lo tanto tampoco aparece en "Lotes
            # asignados" para poder vincularle un lote ahí — pedirlo acá
            # dejaría al usuario sin forma de resolverlo. Se lo salta,
            # EXCEPTO si ya tiene un lote vinculado igual (ej. retorno de
            # una OTT, que reserva el lote vía orden_lotes aunque la
            # fila de orden_materiales no exista o el UPDATE de
            # cantidad_asignada no haya afectado ninguna fila): en ese
            # caso hay un vínculo real esperando a consumirse y no debe
            # perderse en silencio.
            en_ot = query("SELECT 1 FROM orden_materiales WHERE orden_id=? AND material_id=?",
                (d["orden_id"], mat["material_id"]), one=True)
            tiene_vinculo_previo = query("""SELECT 1 FROM orden_lotes
                WHERE orden_id=? AND material_id=?""",
                (d["orden_id"], mat["material_id"]), one=True)
            if not en_ot and not tiene_vinculo_previo:
                continue
            # Si este material ya tiene uno o más lotes vinculados a la
            # OT (de una novedad anterior o de una/varias asignaciones
            # manuales desde "Lotes asignados"), se consume de ESOS
            # lotes — pueden ser VARIOS: si el primero no alcanza para
            # cubrir todo el consumo, se completa con los siguientes
            # lotes vinculados (ej. un lote de 90 + uno de 10, o varios
            # lotes chicos), en orden de ingreso (FIFO).
            vinculos = _lotes_vinculados_material(d["orden_id"], mat["material_id"])
            if not vinculos:
                errores.append(f"Falta vincular un lote para \"{mat['descripcion'] if 'descripcion' in mat.keys() else mat['material_id']}\" — hacelo desde Órdenes de trabajo → Lotes asignados antes de declarar la novedad")
                continue
            # Disponible: los lotes vinculados a esta OT son reservas
            # propias de ella (ver _plan_consumo_adicional) — no se les
            # resta cantidad_reservada, esa resta solo aplica al elegir
            # un lote nuevo desde "Lotes asignados".
            plan, disponible_total, cubierto = _plan_consumo_adicional(vinculos, consumo)
            if not cubierto:
                detalle = ", ".join(f"{l['numero']} (libre {max(0, float(l['cantidad_activa'] or 0))})" for l in vinculos)
                errores.append(f"Stock disponible insuficiente en lote(s) vinculados [{detalle}] (disponible total {disponible_total}, requerido {consumo})")
                continue
            lotes_info[mat["material_id"]] = plan
        if errores:
            return jsonify({"error": "No se puede confirmar la novedad: " + " | ".join(errores)}), 400

    # ── Todas las validaciones pasaron: recién ahora se inserta la novedad ──
    last = query("SELECT numero FROM novedades_produccion ORDER BY id DESC LIMIT 1", one=True)
    try: n = int(last["numero"].split("-")[1])+1 if last else 1
    except: n = 1
    numero = f"NOV-{n:05d}"

    fecha_nov = d.get("fecha") or datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    lid = execute("""INSERT INTO novedades_produccion
        (numero,orden_id,orden_operacion_id,empleado_id,maquina_id,cantidad_producida,tiempo_real_min,
         piezas_observadas,tiempo_perdido,turno,fecha,rendimiento_pct,desvio,obs,creado_por)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (numero,d["orden_id"],d["orden_operacion_id"],d.get("empleado_id"),d.get("maquina_id"),qty,t_real,
         d.get("piezas_observadas") or 0, d.get("tiempo_perdido") or 0,
         d.get("turno"),fecha_nov,rendimiento,desvio,d.get("obs"),session["user_id"]))

    execute("UPDATE orden_operaciones SET qty_producida=qty_producida+? WHERE id=?",
        (qty, d["orden_operacion_id"]))

    # En cuanto se declara la primera novedad de producción, la OT pasa de
    # "Pendiente" a "En proceso" (si ya estaba en otro estado —En proceso,
    # Completada, etc.— no se toca).
    execute("UPDATE ordenes SET estado='En proceso' WHERE id=? AND estado='Pendiente'",
        (d["orden_id"],))

    # ── Si con esta novedad la operación llegó (o superó) el 100% de lo
    # requerido, se marca automáticamente como "Completada". No se toca el
    # estado si la operación ya estaba marcada como Completada de antes
    # (evita pisar, por ejemplo, un estado "Completada" manual con datos
    # distintos) ni si todavía no llegó al 100%. TAMPOCO se auto-completa si
    # la operación YA estaba en o por encima del 100% ANTES de esta novedad
    # (esto pasa cuando el usuario la reabrió manualmente a "En proceso"
    # después de haberla completado antes): en ese caso se le deja seguir
    # cargando novedades libremente y la operación solo vuelve a
    # "Completada" cuando el usuario la marca así manualmente. ─────────────
    ya_estaba_al_100 = qty_req_op > 0 and qty_prod_op >= qty_req_op - 0.0001
    if (qty_req_op > 0 and (qty_prod_op + qty) >= qty_req_op - 0.0001
            and op["estado"] != "Completada" and not ya_estaba_al_100):
        execute("UPDATE orden_operaciones SET estado='Completada' WHERE id=?",
            (d["orden_operacion_id"],))

    # Consumir materias primas/PT vinculadas a un lote: DESCUENTO REAL E
    # INMEDIATO en cuanto se declara la novedad (la novedad ya representa
    # producción efectivamente realizada, así que el material se da por
    # gastado en el momento, sin esperar a que la OT se marque como
    # "Completada"). La vinculación de lote sigue siendo OBLIGATORIA por
    # cada material/PT requerido por la operación, EXCEPTO los de categoría
    # "Insumo": esos no llevan trazabilidad por lote y se descuentan directo
    # del stock general al completar la OT (ver update_orden).
    # La validación de stock ya se hizo arriba (lotes_info).
    if mats_op:
        for mat in mats_op:
            plan = lotes_info.get(mat["material_id"])
            if plan is None:
                # Mismo criterio que en la validación de arriba: material
                # agregado al proceso después de creada la OT, sin lote para
                # vincular todavía — no se descuenta, no rompe la novedad.
                continue
            for lote_activo, consumo in plan:
                # Descuento real: cantidad_disponible, cantidad_activa del lote
                # y stock general del material. También se libera cualquier
                # reserva previa sobre ese mismo lote (p.ej. si se había
                # asignado manualmente desde "Lotes asignados" antes de esta
                # novedad), para no dejar cantidad_reservada desalineada.
                execute("""UPDATE lotes SET
                        cantidad_disponible=MAX(0, cantidad_disponible-?),
                        cantidad_activa=MAX(0, cantidad_activa-?),
                        cantidad_reservada=MAX(0, COALESCE(cantidad_reservada,0)-?),
                        estado=CASE WHEN cantidad_disponible-? <= 0 THEN 'Agotado' ELSE estado END
                    WHERE id=?""", (consumo, consumo, consumo, consumo, lote_activo["id"]))
                execute("""UPDATE materiales SET stock=MAX(0, stock-?), actualizado=datetime('now','localtime')
                    WHERE id=?""", (consumo, mat["material_id"]))
                auto_generar_sc_bajo_stock(mat["material_id"], f"consumo Novedad {numero}")
                # NOTA: NO se vuelve a sumar a orden_materiales.cantidad_asignada
                # acá. Ese campo ya quedó incrementado en el momento en que el
                # lote se vinculó a esta OT (botón "Asignar lote", o el retorno
                # de una OTT), que es justo el requisito para poder entrar a
                # este bloque (_lotes_vinculados_material exige que ya haya un
                # vínculo). Esta novedad solo CONVIERTE esa reserva en consumo
                # real (por eso se descuenta cantidad_reservada arriba); sumarlo
                # de nuevo acá duplicaba el total y hacía que "Lotes asignados"
                # mostrara más cantidad asignada que la que realmente se asignó
                # (ej. reservar 100 y cargar una novedad de 50 mostraba 150).
                # Marcar en orden_lotes cuánto de lo YA ASIGNADO a este lote
                # se consumió realmente. cantidad_usada es el TOTAL
                # comprometido (asignado) para este lote+OT — ya quedó
                # cargado al vincular el lote (Asignar lote / retorno OTT) y
                # NO se vuelve a tocar acá. cantidad_consumida es el
                # subconjunto de ese total que ya se gastó de verdad; es la
                # que avanza con cada novedad (siempre existe la fila porque
                # _lotes_vinculados_material ya exigió el vínculo arriba).
                execute("""UPDATE orden_lotes SET
                        cantidad_consumida=COALESCE(cantidad_consumida,0)+?
                    WHERE orden_id=? AND lote_id=?""",
                    (consumo, d["orden_id"], lote_activo["id"]))
                execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
                    (mat["material_id"], lote_activo["id"], "salida", consumo,
                     f"Consumo real por Novedad {numero} — Lote {lote_activo['numero']} (descuento inmediato)",
                     session["user_id"]))



    # ── Generación inmediata de PT por cajón ────────────────────────────────
    # Si esta novedad es de la ÚLTIMA operación de la ruta, ya representa
    # piezas terminadas: el circuito real es que el operario las deja en
    # bolsa y después las lleva con un cajón a Calidad. Por eso acá se
    # genera/actualiza de inmediato el lote de PT correspondiente al cajón
    # en curso (ver generar_pt_faltante_si_corresponde), en vez de esperar a
    # que toda la OT se marque "Completada" y mezclar todo en un solo lote.
    # Si el producto no tiene capacidad_cajon configurada, esta misma llamada
    # mantiene el comportamiento anterior (un solo lote por OT).
    # Se envuelve en try/except para no perder la novedad ya guardada si algo
    # falla acá: update_orden() vuelve a llamar a esta función como red de
    # seguridad al completar la OT, así que no queda nada sin generar.
    try:
        max_orden = query("""SELECT MAX(CAST(orden AS INTEGER)) mx
            FROM orden_operaciones WHERE orden_id=?""", (d["orden_id"],), one=True)["mx"]
        if max_orden is not None and int(op["orden"]) == int(max_orden):
            generar_pt_faltante_si_corresponde(d["orden_id"])
    except Exception as e:
        print(f"[WARN] No se pudo generar PT/cajón al declarar novedad {numero} (OT {d['orden_id']}): {e}")

    return jsonify({"ok":True,"id":lid,"numero":numero,"rendimiento_pct":rendimiento,"desvio":desvio}), 201






@app.route("/api/novedades/<int:nid>", methods=["GET"])
@login_required()
def get_novedad(nid):
    row = query("""SELECT n.*,e.nombre||' '||e.apellido empleado_nombre,
        m.codigo||' — '||m.nombre maquina_nombre,
        oo.nombre operacion_nombre, oo.orden op_orden,
        oo.proceso_op_id, oo.orden_id,
        o.numero ot_numero, o.producto_id
        FROM novedades_produccion n
        LEFT JOIN empleados e ON e.id=n.empleado_id
        LEFT JOIN maquinas m ON m.id=n.maquina_id
        JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id
        JOIN ordenes o ON o.id=n.orden_id
        WHERE n.id=?""", (nid,), one=True)
    if not row: return jsonify({"error":"Novedad no encontrada"}), 404
    return jsonify(dict(row))

@app.route("/api/novedades/<int:nid>", methods=["PUT"])
@login_required(roles=["admin","operario"])
def update_novedad(nid):
    """Edita una novedad y ajusta stocks/consumos por diferencia."""
    d = request.json
    nov = query("""SELECT n.*,oo.proceso_op_id,oo.orden,oo.orden_id,o.producto_id
        FROM novedades_produccion n
        JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id
        JOIN ordenes o ON o.id=n.orden_id
        WHERE n.id=?""", (nid,), one=True)
    if not nov: return jsonify({"error":"Novedad no encontrada"}), 404

    qty_old = float(nov["cantidad_producida"])
    _qty_raw = d.get("cantidad_producida", None)
    qty_new = qty_old if _qty_raw in (None,"") else float(_qty_raw)
    t_old   = float(nov["tiempo_real_min"])
    t_new   = float(d.get("tiempo_real_min", t_old))
    diff    = qty_new - qty_old  # positive = more produced, negative = less

    # --- Validar stock de insumos si se está aumentando la cantidad ---
    if nov["proceso_op_id"] and diff > 0:
        insumos_op = query("""SELECT om.*, m.descripcion descripcion
            FROM operacion_materiales om JOIN materiales m ON m.id=om.material_id
            WHERE om.operacion_id=? AND m.categoria IN ('Insumo','Herramienta')""", (nov["proceso_op_id"],))
        if insumos_op:
            errores_ins = []
            for ins in insumos_op:
                consumo_incremental = ins["cantidad"] * diff
                comprometido = query("""SELECT COALESCE(SUM(om.cantidad * oo.qty_producida),0) c
                    FROM orden_operaciones oo
                    JOIN operacion_materiales om ON om.operacion_id=oo.proceso_op_id
                    WHERE oo.orden_id=? AND om.material_id=?""",
                    (nov["orden_id"], ins["material_id"]), one=True)["c"] or 0
                mat_stock = query("SELECT stock FROM materiales WHERE id=?", (ins["material_id"],), one=True)
                stock_disp = float(mat_stock["stock"] or 0) if mat_stock else 0
                total_necesario = float(comprometido) + consumo_incremental
                if total_necesario > stock_disp:
                    faltante = round(total_necesario - stock_disp, 3)
                    errores_ins.append(f"Stock insuficiente de insumo \"{ins['descripcion']}\" (stock {stock_disp}, requerido {round(total_necesario,3)}, faltan {faltante})")
            if errores_ins:
                return jsonify({"error": "No se puede confirmar el ajuste: " + " | ".join(errores_ins)}), 400


    # --- Ajustar el CONSUMO REAL de materias primas (diferencia) ---
    # Desde que el material se descuenta al declarar la novedad (ver
    # create_novedad), editar la cantidad producida debe ajustar el stock y
    # el lote ya consumidos por la diferencia, usando el lote que ya estaba
    # vinculado a este material en la OT.
    if diff != 0:
        mats_op = []
        if nov["proceso_op_id"]:
            mats_op = query("""SELECT om.*, m.categoria categoria
                FROM operacion_materiales om JOIN materiales m ON m.id=om.material_id
                WHERE om.operacion_id=?""", (nov["proceso_op_id"],))
            mats_op = [dict(m) for m in mats_op]
        for extra in _materiales_ott_pendientes_por_operacion(nov["orden_id"], nov["orden_operacion_id"]):
            if not any(m["material_id"] == extra["material_id"] for m in mats_op):
                mats_op.append(extra)
        for mat in mats_op:
            if mat["categoria"] in ("Insumo", "Herramienta"):
                continue  # los insumos/herramientas se calculan/descuentan recién al completar la OT
            consumo_diff = mat["cantidad"] * diff  # + = se consume más, - = se devuelve stock
            vinculos = _lotes_vinculados_material(nov["orden_id"], mat["material_id"])
            if not vinculos:
                continue  # no había lote vinculado para este material en esta OT
            if consumo_diff < 0:
                # Se devuelve stock: repartir entre los lotes vinculados
                # (LIFO), igual que al eliminar una novedad, en vez de
                # volcarlo entero a un único lote.
                plan = _plan_devolucion(vinculos, -consumo_diff)
                movs = [(lote_v["id"], lote_v["numero"], devolver) for lote_v, devolver in plan]
                devuelto_total = sum(d for _, _, d in movs)
                faltante = round(-consumo_diff - devuelto_total, 6)
                if faltante > 0.0001:
                    lote_v = vinculos[-1]
                    movs.append((lote_v["id"], lote_v["numero"], faltante))
                for lote_id, lote_num, cant in movs:
                    if cant <= 0: continue
                    execute("""UPDATE lotes SET
                            cantidad_disponible=cantidad_disponible+?,
                            cantidad_activa=cantidad_activa+?,
                            estado=CASE WHEN estado='Agotado' AND cantidad_disponible+?>0 THEN 'Aprobado' ELSE estado END
                        WHERE id=?""", (cant, cant, cant, lote_id))
                    execute("""UPDATE materiales SET stock=stock+?, actualizado=datetime('now','localtime')
                        WHERE id=?""", (cant, mat["material_id"]))
                    # cantidad_usada (total ASIGNADO al lote para esta OT) y
                    # orden_materiales.cantidad_asignada NO se tocan acá: ese
                    # total lo define "Asignar lote", no las novedades. Bajar
                    # la cantidad producida solo revierte lo CONSUMIDO.
                    execute("""UPDATE orden_lotes SET cantidad_consumida=MAX(0,COALESCE(cantidad_consumida,0)-?)
                        WHERE orden_id=? AND lote_id=?""",
                            (cant, nov["orden_id"], lote_id))
                    execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
                            (mat["material_id"], lote_id, "entrada", cant,
                             f"Ajuste consumo {nov['numero']} — Lote {lote_num}", session["user_id"]))
            else:
                # Se consume más: seguir tomando del lote vinculado más
                # reciente (mismo criterio FIFO que create_novedad ya usa
                # para el consumo inicial, vía _plan_consumo_adicional).
                plan, _, cubierto = _plan_consumo_adicional(vinculos, consumo_diff)
                for lote_v, tomar in plan:
                    execute("""UPDATE lotes SET
                            cantidad_disponible=MAX(0, cantidad_disponible-?),
                            cantidad_activa=MAX(0, cantidad_activa-?),
                            cantidad_reservada=MAX(0, COALESCE(cantidad_reservada,0)-?),
                            estado=CASE WHEN cantidad_disponible-? <= 0 THEN 'Agotado' ELSE estado END
                        WHERE id=?""", (tomar, tomar, tomar, tomar, lote_v["id"]))
                    execute("""UPDATE materiales SET stock=MAX(0, stock-?), actualizado=datetime('now','localtime')
                        WHERE id=?""", (tomar, mat["material_id"]))
                    # cantidad_usada / cantidad_asignada NO suben acá: ya
                    # estaban comprometidas desde que se asignó el lote.
                    # Subir la cantidad producida solo convierte más de esa
                    # reserva ya comprometida en consumo real.
                    execute("""UPDATE orden_lotes SET cantidad_consumida=COALESCE(cantidad_consumida,0)+?
                        WHERE orden_id=? AND lote_id=?""",
                            (tomar, nov["orden_id"], lote_v["id"]))
                    execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
                            (mat["material_id"], lote_v["id"], "salida", tomar,
                             f"Ajuste consumo {nov['numero']} — Lote {lote_v['numero']}", session["user_id"]))

    # --- Ajustar qty_producida en orden_operacion ---
    execute("UPDATE orden_operaciones SET qty_producida=MAX(0,qty_producida+?) WHERE id=?",
            (diff, nov["orden_operacion_id"]))

    # --- Sincronizar estado con el 100%: si al editar la novedad la
    # operación pasa a tener 100% o más, se marca "Completada"; si al
    # editarla (achicando la cantidad) queda por debajo del 100% y estaba
    # marcada como Completada, se vuelve a "En proceso" para no dejarla
    # marcada como terminada sin estarlo. No se toca si el estado fue
    # cambiado manualmente a algo distinto de estos dos. ────────────────────
    oo_now = query("SELECT qty_requerida,qty_producida,estado FROM orden_operaciones WHERE id=?",
        (nov["orden_operacion_id"],), one=True)
    if oo_now:
        qty_req_now = float(oo_now["qty_requerida"] or 0)
        qty_prod_now = float(oo_now["qty_producida"] or 0)
        if qty_req_now > 0:
            if qty_prod_now >= qty_req_now - 0.0001 and oo_now["estado"] != "Completada":
                execute("UPDATE orden_operaciones SET estado='Completada' WHERE id=?",
                    (nov["orden_operacion_id"],))
            elif qty_prod_now < qty_req_now - 0.0001 and oo_now["estado"] == "Completada":
                execute("UPDATE orden_operaciones SET estado='En proceso' WHERE id=?",
                    (nov["orden_operacion_id"],))

    # --- Ajustar stock PT si es ultima operacion ---
    max_ord = query("SELECT MAX(CAST(orden AS INTEGER)) mo FROM orden_operaciones WHERE orden_id=?",
                    (nov["orden_id"],), one=True)["mo"]
    if nov["orden"] == max_ord and diff != 0 and nov["producto_id"]:
        prod = query("SELECT * FROM productos WHERE id=?", (nov["producto_id"],), one=True)
        if prod:
            mat_pt = get_or_create_pt_material(prod)
            tipo_pt = "entrada" if diff > 0 else "salida"
            execute("UPDATE materiales SET stock=MAX(0,stock+?),actualizado=datetime('now','localtime') WHERE id=?",
                    (diff, mat_pt["id"]))
            execute("INSERT INTO movimientos (material_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?)",
                    (mat_pt["id"], tipo_pt, abs(diff),
                     f"Ajuste PT {nov['numero']}", session["user_id"]))

    # --- Recalcular rendimiento ---
    std = float(nov["tiempo_ciclo_min"] if hasattr(nov,"tiempo_ciclo_min") else 1) or 1
    op_std = query("SELECT tiempo_ciclo_min FROM proceso_operaciones WHERE id=?",
                   (nov["proceso_op_id"],), one=True) if nov["proceso_op_id"] else None
    ciclo = float(op_std["tiempo_ciclo_min"] or 1) if op_std else 1
    t_perd_new = float(d.get("tiempo_perdido", nov["tiempo_perdido"] if "tiempo_perdido" in nov.keys() else 0) or 0)
    # tiempo_real ya es tiempo neto trabajado; tiempo_perdido es aparte, no se resta.
    t_prod_new = max(t_new, 0.1) if t_new > 0 else 0.1
    rendimiento = round((qty_new / t_prod_new) / (1 / ciclo) * 100, 1) if t_new > 0 else 0
    rendimiento = min(rendimiento, 999)
    desvio = 1 if rendimiento < 80 else 0

    execute("""UPDATE novedades_produccion SET
            cantidad_producida=?, tiempo_real_min=?, empleado_id=?, maquina_id=?,
            piezas_observadas=?, tiempo_perdido=?,
            turno=?, obs=?, rendimiento_pct=?, desvio=?, fecha=?
            WHERE id=?""",
            (qty_new, t_new, d.get("empleado_id", nov["empleado_id"]), d.get("maquina_id", nov["maquina_id"]),
            d.get("piezas_observadas", nov["piezas_observadas"] if "piezas_observadas" in nov.keys() else 0) or 0,
            d.get("tiempo_perdido", nov["tiempo_perdido"] if "tiempo_perdido" in nov.keys() else 0) or 0,
            d.get("turno", nov["turno"]), d.get("obs", nov["obs"]),
            rendimiento, desvio, d.get("fecha", nov["fecha"]), nid))

    return jsonify({"ok": True, "diff": diff, "rendimiento_pct": rendimiento,
                    "desvio": desvio, "ajuste_stock": diff != 0})

@app.route("/api/novedades/<int:nid>", methods=["DELETE"])
@login_required(roles=["admin","operario"])
def delete_novedad(nid):
    """Elimina una novedad y revierte todos sus efectos en stock.
    Antes de borrarla, guarda un registro en novedades_eliminadas con el
    detalle de todo lo que se revirtió (lotes de materia prima, stock de
    producto terminado y remitos que ya hubieran usado ese stock), para
    que quede trazabilidad de qué se eliminó y qué efectos tuvo."""
    import json
    nov = query("""SELECT n.*,oo.proceso_op_id,oo.orden,oo.orden_id,oo.nombre operacion_nombre,
        o.producto_id,o.numero ot_numero,
        p.nombre producto_nombre,
        e.nombre||' '||e.apellido empleado_nombre,
        m.codigo||' — '||m.nombre maquina_nombre,
        u.nombre creado_por_nombre
        FROM novedades_produccion n
        JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id
        JOIN ordenes o ON o.id=n.orden_id
        LEFT JOIN productos p ON p.id=o.producto_id
        LEFT JOIN empleados e ON e.id=n.empleado_id
        LEFT JOIN maquinas m ON m.id=n.maquina_id
        LEFT JOIN usuarios u ON u.id=n.creado_por
        WHERE n.id=?""", (nid,), one=True)
    if not nov: return jsonify({"error":"Novedad no encontrada"}), 404

    qty = float(nov["cantidad_producida"])
    detalle = {"lotes_mp": [], "pt": None, "remitos": []}
    lote_ids_afectados = set()
    pt_lote_ids = set()  # lotes de PT de esta OT — si tienen remitos, se eliminan (no solo se informan)

    # --- Devolver el CONSUMO REAL de materias primas al stock/lote ---
    # Desde que el material se descuenta al declarar la novedad (ver
    # create_novedad), eliminarla debe devolver ese stock ya consumido.
    if nov["proceso_op_id"]:
        mats_op = query("""SELECT om.*, m.categoria categoria, m.descripcion descripcion
            FROM operacion_materiales om JOIN materiales m ON m.id=om.material_id
            WHERE om.operacion_id=?""", (nov["proceso_op_id"],))
        mats_op = [dict(m) for m in mats_op]
    else:
        mats_op = []
    for extra in _materiales_ott_pendientes_por_operacion(nov["orden_id"], nov["orden_operacion_id"]):
        if not any(m["material_id"] == extra["material_id"] for m in mats_op):
            mats_op.append(extra)
    if True:
        for mat in mats_op:
            if mat["categoria"] in ("Insumo", "Herramienta"):
                continue
            consumo = mat["cantidad"] * qty
            # Puede haber consumido de VARIOS lotes (FIFO, ver create_novedad).
            # Repartir la devolución entre todos los lotes vinculados a este
            # material en esta OT (LIFO, sin superar cantidad_usada por
            # lote) en vez de volcarla entera a un único lote.
            vinculos = _lotes_vinculados_material(nov["orden_id"], mat["material_id"])
            if not vinculos:
                continue
            plan = _plan_devolucion(vinculos, consumo)
            if not plan:
                continue
            for lote_v, devolver in plan:
                # Devuelve stock real Y reconstituye la reserva para esta OT
                # (cantidad_reservada), porque el material seguía comprometido
                # con esta OT (orden_materiales.cantidad_asignada no cambia:
                # esa reserva nunca se "gastó" a nivel de total asignado, solo
                # pasaba de reservado a consumido — ahora vuelve a reservado).
                execute("""UPDATE lotes SET
                        cantidad_disponible=cantidad_disponible+?,
                        cantidad_activa=cantidad_activa+?,
                        cantidad_reservada=COALESCE(cantidad_reservada,0)+?,
                        estado=CASE WHEN estado='Agotado' AND cantidad_disponible+?>0 THEN 'Aprobado' ELSE estado END
                    WHERE id=?""", (devolver, devolver, devolver, devolver, lote_v["id"]))
                execute("""UPDATE materiales SET stock=stock+?, actualizado=datetime('now','localtime')
                    WHERE id=?""", (devolver, mat["material_id"]))
                execute("""UPDATE orden_lotes SET cantidad_consumida=MAX(0,COALESCE(cantidad_consumida,0)-?)
                    WHERE orden_id=? AND lote_id=?""",
                        (devolver, nov["orden_id"], lote_v["id"]))
                execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
                        (mat["material_id"], lote_v["id"], "entrada", devolver,
                         f"Reversa {nov['numero']} — devuelve consumo Lote {lote_v['numero']}", session["user_id"]))
                lote_after = query("SELECT numero,estado,cantidad_disponible,cantidad_activa FROM lotes WHERE id=?",
                    (lote_v["id"],), one=True)
                lote_ids_afectados.add(lote_v["id"])
                detalle["lotes_mp"].append({
                    "lote_id": lote_v["id"], "lote_numero": lote_after["numero"],
                    "material": mat["descripcion"], "cantidad_devuelta": round(devolver, 3),
                    "estado_lote": lote_after["estado"],
                    "cantidad_disponible_actual": lote_after["cantidad_disponible"],
                    "cantidad_activa_actual": lote_after["cantidad_activa"]})
            devuelto_total = sum(d for _, d in plan)
            faltante = round(consumo - devuelto_total, 6)
            if faltante > 0.0001:
                # No se pudo repartir todo (cantidad_usada acumulada menor al
                # consumo de esta novedad, p.ej. por consumos de otras
                # novedades ya revertidos). Se devuelve el resto al lote más
                # reciente para no perder stock, mismo criterio que antes.
                lote_v = vinculos[-1]
                execute("""UPDATE lotes SET
                        cantidad_disponible=cantidad_disponible+?,
                        cantidad_activa=cantidad_activa+?,
                        cantidad_reservada=COALESCE(cantidad_reservada,0)+?,
                        estado=CASE WHEN estado='Agotado' AND cantidad_disponible+?>0 THEN 'Aprobado' ELSE estado END
                    WHERE id=?""", (faltante, faltante, faltante, faltante, lote_v["id"]))
                execute("""UPDATE materiales SET stock=stock+?, actualizado=datetime('now','localtime')
                    WHERE id=?""", (faltante, mat["material_id"]))
                execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
                        (mat["material_id"], lote_v["id"], "entrada", faltante,
                         f"Reversa {nov['numero']} — resto devuelto a Lote {lote_v['numero']}", session["user_id"]))
                lote_after = query("SELECT numero,estado,cantidad_disponible,cantidad_activa FROM lotes WHERE id=?",
                    (lote_v["id"],), one=True)
                lote_ids_afectados.add(lote_v["id"])
                detalle["lotes_mp"].append({
                    "lote_id": lote_v["id"], "lote_numero": lote_after["numero"],
                    "material": mat["descripcion"], "cantidad_devuelta": round(faltante, 3),
                    "estado_lote": lote_after["estado"],
                    "cantidad_disponible_actual": lote_after["cantidad_disponible"],
                    "cantidad_activa_actual": lote_after["cantidad_activa"],
                    "nota": "resto (cantidad_usada acumulada insuficiente)"})

    # --- Revertir qty_producida en orden_operacion ---
    execute("UPDATE orden_operaciones SET qty_producida=MAX(0,qty_producida-?) WHERE id=?",
            (qty, nov["orden_operacion_id"]))

    # --- Si al eliminar la novedad la operación queda por debajo del 100%
    # y estaba marcada como Completada (automáticamente por haber llegado al
    # 100%), se revierte a "En proceso". ────────────────────────────────────
    oo_now = query("SELECT qty_requerida,qty_producida,estado FROM orden_operaciones WHERE id=?",
        (nov["orden_operacion_id"],), one=True)
    if oo_now and oo_now["estado"] == "Completada":
        qty_req_now = float(oo_now["qty_requerida"] or 0)
        qty_prod_now = float(oo_now["qty_producida"] or 0)
        if qty_req_now > 0 and qty_prod_now < qty_req_now - 0.0001:
            execute("UPDATE orden_operaciones SET estado='En proceso' WHERE id=?",
                (nov["orden_operacion_id"],))

    # --- Revertir stock PT si era ultima operacion ---
    max_ord = query("SELECT MAX(CAST(orden AS INTEGER)) mo FROM orden_operaciones WHERE orden_id=?",
                    (nov["orden_id"],), one=True)["mo"]
    if nov["orden"] == max_ord and nov["producto_id"]:
        prod = query("SELECT * FROM productos WHERE id=?", (nov["producto_id"],), one=True)
        if prod:
            mat_pt = query("SELECT id FROM materiales WHERE codigo=? AND categoria='Producto terminado'",
                           (prod["codigo"],), one=True)
            if mat_pt:
                execute("UPDATE materiales SET stock=MAX(0,stock-?),actualizado=datetime('now','localtime') WHERE id=?",
                        (qty, mat_pt["id"]))
                execute("INSERT INTO movimientos (material_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?)",
                        (mat_pt["id"], "salida", qty,
                         f"Reversa PT {nov['numero']}", session["user_id"]))
                # Snapshot de los lotes de PT de esta OT (lote único o
                # "cajones" OT-C1, OT-C2...) para que el registro de
                # eliminación muestre en qué estado quedan — incluyendo si
                # ya fueron aprobados por Calidad (stock aprobado).
                lotes_ot = query("""SELECT id,numero,estado,cantidad_original,cantidad_disponible,cantidad_activa
                    FROM lotes WHERE material_id=? AND (numero=? OR numero LIKE ?)
                    ORDER BY numero""", (mat_pt["id"], nov["ot_numero"], nov["ot_numero"]+"-C%"))
                for l in lotes_ot:
                    lote_ids_afectados.add(l["id"])
                    pt_lote_ids.add(l["id"])
                detalle["pt"] = {
                    "material": prod["nombre"],
                    "cantidad_revertida_stock": qty,
                    "lotes_ot": [dict(l) for l in lotes_ot]}

    # --- Remitos que ya hayan entregado el PT de esta OT: al eliminar la
    # novedad se elimina también el ítem del remito (el material fabricado a
    # partir de esa novedad ya no existe). Si el remito queda sin ítems, se
    # anula (no se borra, para conservar el número/historial). ────────────────
    if pt_lote_ids:
        placeholders_pt = ",".join("?" * len(pt_lote_ids))
        remito_items_pt = query(f"""SELECT ri.id ri_id, ri.remito_id, ri.cantidad,
                r.numero remito_numero, r.estado,
                c.razon cliente_nombre, l.numero lote_numero, m.descripcion material
            FROM remito_items ri
            JOIN remitos r ON r.id=ri.remito_id
            JOIN lotes l ON l.id=ri.lote_id
            JOIN materiales m ON m.id=ri.material_id
            LEFT JOIN clientes c ON c.id=r.cliente_id
            WHERE ri.lote_id IN ({placeholders_pt}) AND r.estado!='Anulado'""", tuple(pt_lote_ids))
        remitos_afectados_ids = set()
        for ri in remito_items_pt:
            detalle["remitos"].append({
                "remito_numero": ri["remito_numero"], "fecha": None, "estado": ri["estado"],
                "cliente_nombre": ri["cliente_nombre"], "cantidad": ri["cantidad"],
                "lote_numero": ri["lote_numero"], "material": ri["material"],
                "accion": "Ítem eliminado del remito al eliminar la novedad"})
            execute("DELETE FROM remito_items WHERE id=?", (ri["ri_id"],))
            remitos_afectados_ids.add(ri["remito_id"])
        for rem_id in remitos_afectados_ids:
            quedan = query("SELECT COUNT(*) c FROM remito_items WHERE remito_id=?", (rem_id,), one=True)["c"]
            if quedan == 0:
                execute("UPDATE remitos SET estado='Anulado' WHERE id=?", (rem_id,))

    # --- Remitos que ya hayan usado stock de lotes de MATERIA PRIMA devueltos
    # (caso infrecuente: si se remitió materia prima como tal). Estos NO se
    # eliminan automáticamente, solo quedan informados en el registro. Los
    # remitos de PRODUCTO TERMINADO ya se eliminaron arriba. ─────────────────
    lote_ids_mp = lote_ids_afectados - pt_lote_ids
    if lote_ids_mp:
        placeholders = ",".join("?" * len(lote_ids_mp))
        remitos_rows = query(f"""SELECT r.numero remito_numero, r.fecha, r.estado,
                c.razon cliente_nombre, ri.cantidad, l.numero lote_numero, m.descripcion material
            FROM remito_items ri
            JOIN remitos r ON r.id=ri.remito_id
            JOIN lotes l ON l.id=ri.lote_id
            JOIN materiales m ON m.id=ri.material_id
            LEFT JOIN clientes c ON c.id=r.cliente_id
            WHERE ri.lote_id IN ({placeholders})
            ORDER BY r.fecha DESC""", tuple(lote_ids_mp))
        detalle["remitos"].extend(dict(r) for r in remitos_rows)

    # --- Guardar registro de auditoría antes de borrar la novedad ---
    quien_elimina = query("SELECT nombre FROM usuarios WHERE id=?", (session["user_id"],), one=True)
    execute("""INSERT INTO novedades_eliminadas
        (novedad_numero,orden_id,orden_numero,orden_operacion_id,operacion_nombre,
         producto_id,producto_nombre,empleado_id,empleado_nombre,maquina_id,maquina_nombre,
         cantidad_producida,piezas_observadas,tiempo_real_min,tiempo_perdido,turno,
         fecha_novedad,rendimiento_pct,obs,novedad_creado_por,novedad_creado_por_nombre,
         detalle_json,eliminado_por,eliminado_por_nombre)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (nov["numero"], nov["orden_id"], nov["ot_numero"], nov["orden_operacion_id"], nov["operacion_nombre"],
         nov["producto_id"], nov["producto_nombre"], nov["empleado_id"], nov["empleado_nombre"],
         nov["maquina_id"], nov["maquina_nombre"],
         nov["cantidad_producida"], nov["piezas_observadas"] if "piezas_observadas" in nov.keys() else 0,
         nov["tiempo_real_min"], nov["tiempo_perdido"] if "tiempo_perdido" in nov.keys() else 0, nov["turno"],
         nov["fecha"], nov["rendimiento_pct"], nov["obs"], nov["creado_por"], nov["creado_por_nombre"],
         json.dumps(detalle, ensure_ascii=False), session["user_id"],
         quien_elimina["nombre"] if quien_elimina else None))

    execute("DELETE FROM novedades_produccion WHERE id=?", (nid,))
    return jsonify({"ok": True})


# ── Registro de novedades eliminadas (auditoría) ────────────────────────────
@app.route("/api/novedades-eliminadas", methods=["GET"])
@login_required(roles=["admin","operario"])
def get_novedades_eliminadas():
    import json
    q = (request.args.get("q") or "").strip().lower()
    desde = request.args.get("desde")
    hasta = request.args.get("hasta")
    sql = "SELECT * FROM novedades_eliminadas WHERE 1=1"
    params = []
    if desde: sql += " AND date(eliminado)>=?"; params.append(desde)
    if hasta: sql += " AND date(eliminado)<=?"; params.append(hasta)
    sql += " ORDER BY id DESC LIMIT 500"
    rows = query(sql, tuple(params)) if params else query(sql)
    out = []
    for r in rows:
        d = dict(r)
        try:
            d["detalle"] = json.loads(d.pop("detalle_json") or "{}")
        except Exception:
            d["detalle"] = {}
            d.pop("detalle_json", None)
        out.append(d)
    if q:
        out = [d for d in out if q in (d.get("novedad_numero") or "").lower()
               or q in (d.get("orden_numero") or "").lower()
               or q in (d.get("operacion_nombre") or "").lower()
               or q in (d.get("empleado_nombre") or "").lower()
               or q in (d.get("producto_nombre") or "").lower()]
    return jsonify(out)


@app.route("/api/novedades-eliminadas/<int:eid>/restaurar", methods=["POST"])
@login_required(roles=["admin","operario"])
def restaurar_novedad_eliminada(eid):
    """Deshace una eliminación de novedad: vuelve a crear la novedad con sus
    datos originales y rehace, en sentido inverso, todo lo que
    delete_novedad() había revertido (según el detalle_json guardado):
    re-consume la materia prima de los mismos lotes, repone el stock de
    producto terminado y recrea los ítems de remito que se habían borrado
    (reabriendo el remito si había quedado anulado por eso). Si algo de lo
    referenciado (lote, remito, material) ya no existe o cambió de forma
    incompatible, se avisa mediante "warnings" en la respuesta pero no se
    interrumpe el resto de la restauración."""
    import json
    reg = query("SELECT * FROM novedades_eliminadas WHERE id=?", (eid,), one=True)
    if not reg: return jsonify({"error":"Registro no encontrado"}), 404
    if reg["restaurado"]:
        return jsonify({"error":"Esta novedad ya fue restaurada el "+reg["restaurado"]}), 400

    ya_existe = query("SELECT id FROM novedades_produccion WHERE numero=?", (reg["novedad_numero"],), one=True)
    if ya_existe:
        return jsonify({"error":"Ya existe una novedad con el número "+reg["novedad_numero"]+", no se puede restaurar"}), 400

    oo = query("SELECT * FROM orden_operaciones WHERE id=?", (reg["orden_operacion_id"],), one=True)
    if not oo:
        return jsonify({"error":"La operación de esa orden ya no existe, no se puede restaurar"}), 400
    orden = query("SELECT * FROM ordenes WHERE id=?", (reg["orden_id"],), one=True)
    if not orden:
        return jsonify({"error":"La orden de trabajo ya no existe, no se puede restaurar"}), 400

    try:
        detalle = json.loads(reg["detalle_json"] or "{}")
    except Exception:
        detalle = {}

    warnings = []
    qty = float(reg["cantidad_producida"] or 0)

    # --- Volver a crear la novedad con sus datos originales ---
    execute("""INSERT INTO novedades_produccion
        (numero,orden_id,orden_operacion_id,empleado_id,maquina_id,cantidad_producida,tiempo_real_min,
         piezas_observadas,tiempo_perdido,turno,fecha,rendimiento_pct,desvio,obs,creado_por)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (reg["novedad_numero"], reg["orden_id"], reg["orden_operacion_id"], reg["empleado_id"], reg["maquina_id"],
         qty, reg["tiempo_real_min"], reg["piezas_observadas"] or 0, reg["tiempo_perdido"] or 0, reg["turno"],
         reg["fecha_novedad"], reg["rendimiento_pct"], 1 if (reg["rendimiento_pct"] or 0) < 80 else 0,
         reg["obs"], reg["novedad_creado_por"]))

    # --- Rehacer qty_producida y estado de la operación / OT (mismo criterio que create_novedad) ---
    qty_req_op = float(oo["qty_requerida"] or 0)
    qty_prod_antes = float(oo["qty_producida"] or 0)
    execute("UPDATE orden_operaciones SET qty_producida=qty_producida+? WHERE id=?", (qty, reg["orden_operacion_id"]))
    execute("UPDATE ordenes SET estado='En proceso' WHERE id=? AND estado='Pendiente'", (reg["orden_id"],))
    ya_estaba_al_100 = qty_req_op > 0 and qty_prod_antes >= qty_req_op - 0.0001
    if (qty_req_op > 0 and (qty_prod_antes + qty) >= qty_req_op - 0.0001
            and oo["estado"] != "Completada" and not ya_estaba_al_100):
        execute("UPDATE orden_operaciones SET estado='Completada' WHERE id=?", (reg["orden_operacion_id"],))

    # --- Re-consumir la materia prima de los mismos lotes que se habían devuelto ---
    for l in detalle.get("lotes_mp") or []:
        lote_id = l.get("lote_id")
        consumo = float(l.get("cantidad_devuelta") or 0)
        if not lote_id or consumo <= 0: continue
        lote = query("SELECT * FROM lotes WHERE id=?", (lote_id,), one=True)
        if not lote:
            warnings.append("El lote "+str(l.get("lote_numero") or lote_id)+" ya no existe: no se pudo re-consumir "+str(consumo))
            continue
        execute("""UPDATE lotes SET
                cantidad_disponible=MAX(0,cantidad_disponible-?),
                cantidad_activa=MAX(0,cantidad_activa-?),
                cantidad_reservada=MAX(0,COALESCE(cantidad_reservada,0)-?),
                estado=CASE WHEN cantidad_disponible-?<=0 THEN 'Agotado' ELSE estado END
            WHERE id=?""", (consumo, consumo, consumo, consumo, lote_id))
        execute("""UPDATE materiales SET stock=MAX(0,stock-?), actualizado=datetime('now','localtime')
            WHERE id=?""", (consumo, lote["material_id"]))
        # cantidad_usada / cantidad_asignada NO se tocan: la reserva de este
        # lote para esta OT ya estaba comprometida antes de la novedad
        # original (se había restaurado cantidad_reservada al eliminarla).
        # Re-consumir solo vuelve a convertir esa reserva en consumo real.
        existing_ol = query("SELECT id FROM orden_lotes WHERE orden_id=? AND lote_id=?", (reg["orden_id"], lote_id), one=True)
        if existing_ol:
            execute("""UPDATE orden_lotes SET cantidad_consumida=COALESCE(cantidad_consumida,0)+?
                WHERE orden_id=? AND lote_id=?""", (consumo, reg["orden_id"], lote_id))
        else:
            # No debería pasar en circunstancias normales (el vínculo se
            # crea al asignar el lote), pero por las dudas se preserva como
            # red de seguridad si el vínculo ya no existiera.
            execute("""INSERT INTO orden_lotes (orden_id,lote_id,material_id,cantidad_usada,cantidad_consumida)
                VALUES (?,?,?,?,?)""", (reg["orden_id"], lote_id, lote["material_id"], consumo, consumo))
            execute("""UPDATE orden_materiales SET cantidad_asignada=cantidad_asignada+?
                WHERE orden_id=? AND material_id=?""", (consumo, reg["orden_id"], lote["material_id"]))
        execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
            (lote["material_id"], lote_id, "salida", consumo,
             f"Restauración {reg['novedad_numero']} — re-consume Lote {lote['numero']}", session["user_id"]))

    # --- Reponer el stock de producto terminado revertido ---
    pt = detalle.get("pt")
    if pt:
        prod = query("SELECT * FROM productos WHERE id=?", (reg["producto_id"],), one=True) if reg["producto_id"] else None
        mat_pt = query("SELECT id FROM materiales WHERE codigo=? AND categoria='Producto terminado'",
                       (prod["codigo"],), one=True) if prod else None
        if mat_pt:
            qty_pt = float(pt.get("cantidad_revertida_stock") or 0)
            execute("UPDATE materiales SET stock=stock+?, actualizado=datetime('now','localtime') WHERE id=?",
                    (qty_pt, mat_pt["id"]))
            execute("INSERT INTO movimientos (material_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?)",
                    (mat_pt["id"], "entrada", qty_pt, f"Restauración PT {reg['novedad_numero']}", session["user_id"]))
        else:
            warnings.append("No se encontró el material de producto terminado: no se pudo reponer el stock de PT")

    # --- Recrear ítems de remito que se habían eliminado, y reabrir el remito si quedó anulado ---
    for r in detalle.get("remitos") or []:
        if not r.get("accion"): continue  # remitos de MP: solo informativos, no se tocaron al eliminar
        remito = query("SELECT * FROM remitos WHERE numero=?", (r.get("remito_numero"),), one=True)
        lote_r = query("SELECT * FROM lotes WHERE numero=?", (r.get("lote_numero"),), one=True)
        if not remito or not lote_r:
            warnings.append("No se pudo recrear el ítem del remito "+str(r.get("remito_numero") or "—")+" (remito o lote ya no existen)")
            continue
        execute("""INSERT INTO remito_items (remito_id,material_id,lote_id,cantidad,obs)
            VALUES (?,?,?,?,?)""",
            (remito["id"], lote_r["material_id"], lote_r["id"], r.get("cantidad") or 0,
             "Restaurado automáticamente al restaurar novedad "+reg["novedad_numero"]))
        if remito["estado"] == "Anulado":
            nuevo_estado = r.get("estado") or "Emitido"
            execute("UPDATE remitos SET estado=? WHERE id=?", (nuevo_estado, remito["id"]))

    # --- Marcar el registro de auditoría como restaurado (se conserva el historial) ---
    quien = query("SELECT nombre FROM usuarios WHERE id=?", (session["user_id"],), one=True)
    execute("""UPDATE novedades_eliminadas SET restaurado=datetime('now','localtime'),
            restaurado_por=?, restaurado_por_nombre=? WHERE id=?""",
        (session["user_id"], quien["nombre"] if quien else None, eid))

    return jsonify({"ok": True, "numero": reg["novedad_numero"], "warnings": warnings})


# ── Trabajo no productivo ──────────────────────────────────────────────────────
@app.route("/api/trabajo-no-productivo", methods=["GET"])
@login_required()
def get_trabajo_no_productivo():
    emp_id = request.args.get("emp_id")
    desde = request.args.get("desde")
    hasta = request.args.get("hasta")
    sql = """SELECT t.*, e.nombre||' '||e.apellido empleado_nombre
        FROM trabajo_no_productivo t
        LEFT JOIN empleados e ON e.id=t.empleado_id
        WHERE 1=1"""
    params = []
    if emp_id:
        sql += " AND t.empleado_id=?"
        params.append(emp_id)
    if desde:
        sql += " AND date(t.fecha)>=?"
        params.append(desde)
    if hasta:
        sql += " AND date(t.fecha)<=?"
        params.append(hasta)
    sql += " ORDER BY t.fecha DESC, t.id DESC"
    if not emp_id:
        sql += " LIMIT 200"
    rows = query(sql, tuple(params))
    return jsonify([dict(r) for r in rows])

@app.route("/api/trabajo-no-productivo", methods=["POST"])
@login_required(roles=["admin","operario"])
def create_trabajo_no_productivo():
    d = request.json
    desc = (d.get("descripcion") or "").strip()
    tmin = float(d.get("tiempo_min") or 0)
    fecha = (d.get("fecha") or "").strip()
    if not desc: return jsonify({"error":"Descripción requerida"}), 400
    if tmin <= 0: return jsonify({"error":"El tiempo debe ser mayor a 0"}), 400

    last = query("SELECT numero FROM trabajo_no_productivo ORDER BY id DESC LIMIT 1", one=True)
    try: n = int(last["numero"].split("-")[1])+1 if last else 1
    except: n = 1
    numero = f"TNP-{n:05d}"

    if fecha:
        lid = execute("""INSERT INTO trabajo_no_productivo
            (numero,empleado_id,descripcion,tiempo_min,fecha,creado_por)
            VALUES (?,?,?,?,?,?)""",
            (numero, d.get("empleado_id") or None, desc, tmin, fecha, session["user_id"]))
    else:
        lid = execute("""INSERT INTO trabajo_no_productivo
            (numero,empleado_id,descripcion,tiempo_min,creado_por)
            VALUES (?,?,?,?,?)""",
            (numero, d.get("empleado_id") or None, desc, tmin, session["user_id"]))
    return jsonify({"ok":True,"id":lid,"numero":numero}), 201

@app.route("/api/trabajo-no-productivo/<int:tid>", methods=["PUT"])
@login_required(roles=["admin","operario"])
def update_trabajo_no_productivo(tid):
    row = query("SELECT id FROM trabajo_no_productivo WHERE id=?", (tid,), one=True)
    if not row: return jsonify({"error":"Registro no encontrado"}), 404
    d = request.json
    desc = (d.get("descripcion") or "").strip()
    tmin = float(d.get("tiempo_min") or 0)
    fecha = (d.get("fecha") or "").strip()
